insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('energy-budget-weekly-planner', 'Energy Budget Weekly Planner', 'worksheet'::resource_kind, 'A one-page planner where a client spreads limited energy across the week by listing what gives and drains it.', 'Use it to help a client plan a week around real energy rather than good intentions.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through one ordinary week with the client and let them place their own activities on the page. Notice whether the drains outnumber the refuels and whether anything on the list is there out of obligation alone. Invite the client to move one item rather than overhaul the week, and look at the plan together the next time you meet.', '[{"id": "f0", "type": "textarea", "label": "Things that drain my energy"}, {"id": "f1", "type": "textarea", "label": "Things that give me energy back"}, {"id": "f2", "type": "textarea", "label": "What I need to do this week no matter what"}, {"id": "f3", "type": "textarea", "label": "One thing I can move, shrink or share"}, {"id": "f4", "type": "textarea", "label": "What a good-enough week looks like for me"}]'::jsonb, array['planning', 'routines']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('decision-pros-and-cons-with-values-column', 'Decision Pros and Cons With Values Column', 'worksheet'::resource_kind, 'A decision grid with a fifth column that asks which values each option serves.', 'Use it to help a client weigh a choice by what matters to them, not only by pros and cons.', array['Adults']::text[], '30 minutes', 'Pick a real decision the client is facing and fill the grid in session. The values column often shifts the conversation, because a long list of pros can matter less than one value that keeps showing up. Let the client do the writing and resist steering toward an answer; the page is there to slow the decision down, not to settle it.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing"}, {"id": "f1", "type": "textarea", "label": "Option A: what it gives me and costs me"}, {"id": "f2", "type": "textarea", "label": "Option B: what it gives me and costs me"}, {"id": "f3", "type": "textarea", "label": "The values each option serves"}, {"id": "f4", "type": "textarea", "label": "What I notice when I read it all back"}, {"id": "f5", "type": "textarea", "label": "My next small step on this decision"}]'::jsonb, array['planning', 'values']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('one-line-boundary-sentence-builder', 'One-Line Boundary Sentence Builder', 'worksheet'::resource_kind, 'A fill-in page for drafting a short, kind, firm sentence to use when saying no.', 'Use it to help a client prepare the words for a boundary before the moment arrives.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one situation the client has been avoiding and build the sentence together, then say it aloud in session. Clients often draft something long and apologetic; invite them to cut it down to one clear line. Practice out loud matters more than the written version, and the page can go in a pocket or a phone note afterward.', '[{"id": "f0", "type": "textarea", "label": "The situation where I need a boundary"}, {"id": "f1", "type": "textarea", "label": "What I want to happen instead"}, {"id": "f2", "type": "textarea", "label": "My one-sentence boundary"}, {"id": "f3", "type": "textarea", "label": "What I might be tempted to add or apologize for"}, {"id": "f4", "type": "textarea", "label": "What I will do if the other person pushes back"}, {"id": "f5", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['assertiveness', 'communication']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('sleep-wind-down-routine-designer', 'Sleep Wind-Down Routine Designer', 'worksheet'::resource_kind, 'A page for a client to design an evening routine step by step, from last screen to lights out.', 'Use it to help a client shape an evening routine they can actually keep.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client already does in the hour before bed and build from there instead of handing over a standard list. Aim for three or four steps they believe they could do on a tired night. Check in the next session about which steps survived the week and which were quietly dropped, and treat dropped steps as information.', '[{"id": "f0", "type": "textarea", "label": "What my last hour before bed looks like now"}, {"id": "f1", "type": "textarea", "label": "Things that help me wind down"}, {"id": "f2", "type": "textarea", "label": "Things that wind me up that I could move earlier"}, {"id": "f3", "type": "textarea", "label": "My three or four step routine"}, {"id": "f4", "type": "textarea", "label": "What I will do if I cannot fall asleep"}, {"id": "f5", "type": "textarea", "label": "What might get in the way and what I will do about it"}]'::jsonb, array['sleep', 'routines']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('support-network-map-with-roles', 'Support Network Map With Roles', 'worksheet'::resource_kind, 'A page for mapping who helps with what: practical help, listening, fun and honest feedback.', 'Use it to help a client see which kinds of support they have and which are thin.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client write names in circles by role, since one person rarely covers everything. Gaps are worth noticing without judgment; a client may have plenty of fun people and no one to call on a bad night. Choose one gap to work on together, such as one small ask of one person this week, and revisit it next session.', '[{"id": "f0", "type": "textarea", "label": "People I can turn to for practical help"}, {"id": "f1", "type": "textarea", "label": "People who listen well"}, {"id": "f2", "type": "textarea", "label": "People I have fun with"}, {"id": "f3", "type": "textarea", "label": "People who tell me the truth kindly"}, {"id": "f4", "type": "textarea", "label": "A role that feels thin right now"}, {"id": "f5", "type": "textarea", "label": "One small ask I could make this week"}]'::jsonb, array['support', 'connection']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('three-column-thought-record-starter', 'Three Column Thought Record Starter', 'cbt'::resource_kind, 'A beginner thought record with three columns: situation, thought and feeling, plus a first balanced thought.', 'Use it to introduce thought records with fewer columns before the full version.', array['Adults', 'Teens']::text[], '25 minutes', 'Do the first one together in session using a recent, mildly upsetting moment rather than the worst week. Keep the focus on separating what happened from what the mind said about it. Many clients stall on the balanced thought; accept a modest one such as "maybe, but not certain" and build from there across later weeks.', '[{"id": "f0", "type": "textarea", "label": "The situation in a sentence"}, {"id": "f1", "type": "textarea", "label": "The thought that went through my mind"}, {"id": "f2", "type": "textarea", "label": "The feeling and how strong it was from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What else could be true"}, {"id": "f4", "type": "textarea", "label": "A more balanced thought I could try on"}, {"id": "f5", "type": "textarea", "label": "How strong the feeling is now from 0 to 10"}]'::jsonb, array['core CBT', 'automatic thoughts']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('downward-arrow-meaning-chain', 'Downward Arrow Meaning Chain', 'cbt'::resource_kind, 'A page that follows a thought down through "and what would that mean?" questions to a deeper belief.', 'Use it to help a client trace a surface thought to the belief underneath it.', array['Adults']::text[], '30 minutes', 'Start with one automatic thought and keep asking what it would mean about the client until a core statement appears, then stop and check in on how the client is doing. This can stir feelings, so pace it and leave time to step back. The belief that surfaces becomes material for later work, not a conclusion about the client.', '[{"id": "f0", "type": "textarea", "label": "The thought I started with"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean?"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what would it mean?"}, {"id": "f3", "type": "textarea", "label": "The belief at the bottom, in my own words"}, {"id": "f4", "type": "textarea", "label": "How strongly I believe it from 0 to 100"}, {"id": "f5", "type": "textarea", "label": "What I notice in my body as I write this"}, {"id": "f6", "type": "textarea", "label": "Something that is also true about me"}]'::jsonb, array['core CBT', 'core beliefs']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('fortune-telling-prediction-tracker', 'Fortune Telling Prediction Tracker', 'cbt'::resource_kind, 'A tracker for writing down a prediction before an event and what really happened afterward.', 'Use it to help a client test their forecasts against real outcomes over several days.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to write each prediction before the event and rate how sure they are, then return to it afterward. The value comes from the pattern across several entries, not any one result. Look together for predictions that were close, ones that were far off, and the ones the client never got to test because they avoided the event.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen"}, {"id": "f1", "type": "textarea", "label": "How sure I am from 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I will watch for"}, {"id": "f3", "type": "textarea", "label": "What really happened"}, {"id": "f4", "type": "textarea", "label": "How close my prediction was"}, {"id": "f5", "type": "textarea", "label": "What I will take from this for the next prediction"}]'::jsonb, array['core CBT', 'behavioral experiment', 'thinking traps']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('responsibility-pie-chart-worksheet', 'Responsibility Pie Chart Worksheet', 'cbt'::resource_kind, 'A pie chart exercise for dividing responsibility for an outcome among all the factors involved.', 'Use it to help a client see all the contributors to an outcome, not only themselves.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client list every factor that played a part before drawing any slices, and save themselves for last. Clients who over-own outcomes usually run out of pie quickly. Notice how the client reacts to a smaller slice; relief, doubt and guilt are all common, and each is worth a conversation rather than a correction.', '[{"id": "f0", "type": "textarea", "label": "The outcome I feel responsible for"}, {"id": "f1", "type": "textarea", "label": "Everyone and everything else that played a part"}, {"id": "f2", "type": "textarea", "label": "My slice, drawn last, and why"}, {"id": "f3", "type": "textarea", "label": "How I feel looking at the whole pie"}, {"id": "f4", "type": "textarea", "label": "What is still mine to learn from or repair"}, {"id": "f5", "type": "textarea", "label": "What I would say to a friend in this spot"}]'::jsonb, array['core CBT', 'self-criticism', 'thinking traps']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('worry-time-and-action-sorting-page', 'Worry Time and Action Sorting Page', 'cbt'::resource_kind, 'A page for sorting worries into ones with a next step and ones to set down, tied to a daily worry slot.', 'Use it to help a client separate worries they can act on from ones they cannot.', array['Adults']::text[], 'Ten minutes daily for two weeks', 'Introduce a fixed daily slot and have the client jot worries as they come, then sort them during the slot. Actionable worries get one small step with a date; the rest get a note and a deliberate set-down. Expect the sorting to feel odd at first and review the page together to see which pile fills faster.', '[{"id": "f0", "type": "textarea", "label": "Worries I jotted down today"}, {"id": "f1", "type": "textarea", "label": "Worries I can do something about"}, {"id": "f2", "type": "textarea", "label": "One small step and when I will do it"}, {"id": "f3", "type": "textarea", "label": "Worries I cannot act on today"}, {"id": "f4", "type": "textarea", "label": "How I will set those down"}, {"id": "f5", "type": "textarea", "label": "How I felt when the slot was over"}]'::jsonb, array['core CBT', 'worry', 'planning']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-defusion-practice', 'Leaves on a Stream Defusion Practice', 'act'::resource_kind, 'A guided practice where thoughts are placed on leaves floating down a stream, with space to log the experience.', 'Use it to help a client practice watching thoughts pass without grabbing them.', array['Adults', 'Teens']::text[], '20 minutes', 'Lead the image slowly in session, then ask what it was like rather than whether it worked. Many clients find their mind keeps wandering off the stream, which is the practice itself. Offer it as one way of relating to thoughts and invite the client to try short rounds at home on a day that is not already hard.', '[{"id": "f0", "type": "textarea", "label": "What my mind put on the leaves"}, {"id": "f1", "type": "textarea", "label": "When I got pulled into the thought"}, {"id": "f2", "type": "textarea", "label": "How I noticed and came back"}, {"id": "f3", "type": "textarea", "label": "What the thoughts felt like when they were on leaves"}, {"id": "f4", "type": "textarea", "label": "Where I could try this in my week"}]'::jsonb, array['core ACT', 'defusion', 'mindfulness']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('values-versus-goals-sorting-page', 'Values Versus Goals Sorting Page', 'act'::resource_kind, 'A page that separates directions to keep walking from finish lines to cross.', 'Use it to help a client tell a value from a goal and link one to the other.', array['Adults']::text[], '30 minutes', 'Ask the client for a goal they care about, then ask what it is in service of, until a direction appears. A value cannot be finished; a goal can be ticked off. Clients sometimes list what others want for them, so gently ask whose voice each item carries and keep the final list in their own words.', '[{"id": "f0", "type": "textarea", "label": "A goal I am working toward"}, {"id": "f1", "type": "textarea", "label": "The value underneath that goal"}, {"id": "f2", "type": "textarea", "label": "A value that has no finish line"}, {"id": "f3", "type": "textarea", "label": "A way I could live that value today in a small way"}, {"id": "f4", "type": "textarea", "label": "Something I do that does not match this value"}, {"id": "f5", "type": "textarea", "label": "What I want to move toward this week"}]'::jsonb, array['core ACT', 'values', 'committed action']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-rehearsal-page', 'Passengers on the Bus Rehearsal Page', 'act'::resource_kind, 'A page built on the passengers on the bus metaphor, with space to name the passengers and the direction.', 'Use it to help a client keep driving toward a value with difficult passengers aboard.', array['Adults', 'Teens']::text[], '30 minutes', 'Let the client name the passengers, such as doubt or fear, and the place the bus is headed. Passengers shout and the driver still chooses the route. Ask what the client has tried to get passengers off the bus and what it cost. Keep the tone light, and ask about a concrete turn they could take this week.', '[{"id": "f0", "type": "textarea", "label": "Where my bus is headed"}, {"id": "f1", "type": "textarea", "label": "The passengers who shout the loudest"}, {"id": "f2", "type": "textarea", "label": "What they say"}, {"id": "f3", "type": "textarea", "label": "What I have done to try to throw them off"}, {"id": "f4", "type": "textarea", "label": "What it cost me"}, {"id": "f5", "type": "textarea", "label": "The next turn I will take with them on board"}]'::jsonb, array['core ACT', 'metaphor', 'values']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('self-compassion-break-practice-card', 'Self-Compassion Break Practice Card', 'act'::resource_kind, 'A short pause card with three steps: notice the pain, remember others feel it, and offer a kind phrase.', 'Use it to give a client a brief pause to use in a hard moment.', array['Adults', 'Teens']::text[], 'Five minutes', 'Practice the three steps once in session using a mild, current difficulty. Let the client choose a phrase that sounds like them rather than a script, since borrowed phrases often ring false. Ask how a hand on the chest or a deep breath lands, and treat any discomfort with kindness toward oneself as worth talking about.', '[{"id": "f0", "type": "textarea", "label": "What is hard for me right now"}, {"id": "f1", "type": "textarea", "label": "How others also meet something like this"}, {"id": "f2", "type": "textarea", "label": "A kind phrase in my own words"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body as I said it"}, {"id": "f4", "type": "textarea", "label": "Where I could use this card this week"}]'::jsonb, array['core ACT', 'self-compassion']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('willingness-dial-check-in', 'Willingness Dial Check-In', 'act'::resource_kind, 'A dial from 0 to 10 that asks how willing a client is to feel something in order to do something that matters.', 'Use it to help a client gauge willingness before choosing a next step.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to pick a valued step and rate willingness to feel what comes with it. A middle number is useful: ask what would move it up or down by one. Smaller steps often raise the number. Treat a low rating as information about the size of the step, not as resistance, and plan the step the client rates highest.', '[{"id": "f0", "type": "textarea", "label": "A step that matters to me"}, {"id": "f1", "type": "textarea", "label": "The feelings that come with it"}, {"id": "f2", "type": "textarea", "label": "My willingness from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What would raise it by one point"}, {"id": "f4", "type": "textarea", "label": "A smaller version of the step"}, {"id": "f5", "type": "textarea", "label": "When I will try it"}]'::jsonb, array['core ACT', 'willingness', 'committed action']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('please-basics-seven-day-tracker', 'PLEASE Basics Seven-Day Tracker', 'dbt'::resource_kind, 'A tracker for the PLEASE skills: physical illness, eating, avoiding mood-altering substances, sleep and exercise.', 'Use it to help a client watch the basics that make emotions harder or easier to manage.', array['Adults', 'Teens']::text[], 'One week', 'Review the five areas together and let the client pick one to work on instead of all five. Notice where an area is steady and name it as a strength. For the line on substances, keep the tone curious and nonjudgmental. Go over the tracker the following session and look for links between the basics and hard days.', '[{"id": "f0", "type": "textarea", "label": "My sleep this week"}, {"id": "f1", "type": "textarea", "label": "My eating pattern this week"}, {"id": "f2", "type": "textarea", "label": "Movement I got this week"}, {"id": "f3", "type": "textarea", "label": "Substance use this week, in my own words"}, {"id": "f4", "type": "textarea", "label": "Anything about my physical health that needs attention"}, {"id": "f5", "type": "textarea", "label": "The one area I will work on"}]'::jsonb, array['core DBT', 'emotion regulation', 'self-monitoring']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-coping-statements-page', 'Radical Acceptance Coping Statements Page', 'dbt'::resource_kind, 'A page for drafting short statements that help a client accept a painful fact that cannot be changed.', 'Use it to help a client practice accepting a reality without approving of it.', array['Adults']::text[], '30 minutes', 'Choose a situation that cannot change and keep the page about acceptance, not approval. Write statements together and see which ones the client can say without arguing with them. Acceptance is practiced in small rounds and often comes with sadness; leave time for that. Revisit the statements across several sessions.', '[{"id": "f0", "type": "textarea", "label": "The fact I am struggling to accept"}, {"id": "f1", "type": "textarea", "label": "What I wish were different"}, {"id": "f2", "type": "textarea", "label": "What accepting it does not mean"}, {"id": "f3", "type": "textarea", "label": "A statement I can say to myself about it"}, {"id": "f4", "type": "textarea", "label": "What I notice in my body when I say it"}, {"id": "f5", "type": "textarea", "label": "One thing I can still choose"}]'::jsonb, array['core DBT', 'distress tolerance', 'acceptance']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('fast-skill-self-respect-rehearsal', 'FAST Skill Self-Respect Rehearsal', 'dbt'::resource_kind, 'A rehearsal page for the FAST skills: fair, apologies only when warranted, stick to values, truthful.', 'Use it to help a client keep self-respect while asking for something or saying no.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick a real interaction and rehearse it aloud, noting where the client slides into over-apologizing or bending the truth. Pair it with the DEAR MAN page if the client has it. Most clients benefit from naming which letter is hardest and rehearsing that line a few times before the conversation happens.', '[{"id": "f0", "type": "textarea", "label": "The conversation I need to have"}, {"id": "f1", "type": "textarea", "label": "What is fair to myself and the other person"}, {"id": "f2", "type": "textarea", "label": "Where I tend to apologize too much"}, {"id": "f3", "type": "textarea", "label": "The value I want to stick to"}, {"id": "f4", "type": "textarea", "label": "The honest line I will use"}, {"id": "f5", "type": "textarea", "label": "How I will feel if it goes badly"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-urges-grid', 'Pros and Cons of Acting on Urges Grid', 'dbt'::resource_kind, 'A four-box grid for weighing short-term and long-term pros and cons of acting on an urge versus resisting it.', 'Use it to help a client slow down before acting on a strong urge.', array['Adults', 'Teens']::text[], '30 minutes', 'Fill all four boxes honestly, since the pros of acting on the urge are real and skipping them rings false. Clients often find the long-term column does the work. Keep a copy somewhere handy for the next time an urge hits, and ask what could make the long-term boxes feel closer in the moment.', '[{"id": "f0", "type": "textarea", "label": "The urge I want to look at"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on it"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on it"}, {"id": "f3", "type": "textarea", "label": "Pros of resisting it"}, {"id": "f4", "type": "textarea", "label": "Cons of resisting it"}, {"id": "f5", "type": "textarea", "label": "What I choose to do next time"}, {"id": "f6", "type": "textarea", "label": "What will help me remember this grid"}]'::jsonb, array['core DBT', 'distress tolerance', 'urges']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('wise-mind-accepts-distraction-menu', 'Wise Mind ACCEPTS Distraction Menu', 'dbt'::resource_kind, 'A menu of distraction ideas arranged by the ACCEPTS letters, with space for personal picks.', 'Use it to help a client build a list of distractions that suit them.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through each letter and ask the client what has worked for them before, then fill in the menu together. Distraction is a short-term tool for getting through a wave, not a way to avoid the feeling for good. Ask the client to try two items before the next session and bring back what helped and what did not.', '[{"id": "f0", "type": "textarea", "label": "Activities I could do (A)"}, {"id": "f1", "type": "textarea", "label": "Ways to help someone else (C)"}, {"id": "f2", "type": "textarea", "label": "Comparisons that put things in perspective (C)"}, {"id": "f3", "type": "textarea", "label": "Emotions I could bring in on purpose (E)"}, {"id": "f4", "type": "textarea", "label": "Pushing away for a short while (P)"}, {"id": "f5", "type": "textarea", "label": "Thoughts and sensations to occupy me (T and S)"}, {"id": "f6", "type": "textarea", "label": "My top three picks"}]'::jsonb, array['core DBT', 'distress tolerance', 'skills']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('appreciation-exchange-sheet', 'Appreciation Exchange Sheet', 'couples'::resource_kind, 'Both partners write specific appreciations and read them aloud to each other.', 'Use it to help partners practice noticing and voicing what they value in each other.', array['Couples']::text[], '20 minutes', 'Each partner fills in their own side first, then reads to the other while the listener only says thank you. Specifics matter: "you made coffee while I was rushing" lands better than "you are great." Watch for one partner struggling to find items and slow down rather than push; the quiet moments are part of the work.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something specific my partner did this week"}, {"id": "f1", "type": "textarea", "label": "Partner A: what it meant to me"}, {"id": "f2", "type": "textarea", "label": "Partner B: something specific my partner did this week"}, {"id": "f3", "type": "textarea", "label": "Partner B: what it meant to me"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear it from my partner"}, {"id": "f5", "type": "textarea", "label": "One appreciation each of us will say out loud this week"}]'::jsonb, array['Gottman', 'connection', 'couples']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('gentle-start-up-rewrite-page', 'Gentle Start-Up Rewrite Page', 'couples'::resource_kind, 'Partners rewrite a harsh opening line into a gentle one with a feeling, a situation and a request.', 'Use it to help partners begin hard topics in a way that keeps the other person listening.', array['Couples']::text[], '30 minutes', 'Each partner brings a recent complaint as it was first said, then rewrites it using "I feel, about what, and I need." Practice saying the new version aloud in session. Expect some stiffness at first; the point is the shape of the sentence. Listeners reflect back what they heard before responding.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I said it the first time"}, {"id": "f1", "type": "textarea", "label": "Partner A: my rewrite with a feeling and a request"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I said it the first time"}, {"id": "f3", "type": "textarea", "label": "Partner B: my rewrite with a feeling and a request"}, {"id": "f4", "type": "textarea", "label": "How each version might feel to hear"}, {"id": "f5", "type": "textarea", "label": "A topic we will start gently this week"}]'::jsonb, array['Gottman', 'communication', 'couples']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('shared-calendar-and-chore-fairness-talk', 'Shared Calendar and Chore Fairness Talk', 'couples'::resource_kind, 'A guided talk for partners to list household tasks, who does what and what feels fair.', 'Use it to help partners talk through the division of everyday tasks without blame.', array['Couples']::text[], 'Full session', 'Have both partners list tasks, including the invisible ones such as planning and remembering, then compare lists. Differences in what each sees are often the first surprise. Keep the conversation about the shared load, not who is at fault, and end with one change each partner agrees to try for a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry, including the invisible ones"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry, including the invisible ones"}, {"id": "f2", "type": "textarea", "label": "Tasks we both forget or avoid"}, {"id": "f3", "type": "textarea", "label": "What feels unfair to each of us"}, {"id": "f4", "type": "textarea", "label": "What each of us appreciates about the other''s load"}, {"id": "f5", "type": "textarea", "label": "One change we will each try this week"}]'::jsonb, array['relationship issues', 'planning', 'couples']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('trust-rebuilding-small-promises-log', 'Trust Rebuilding Small Promises Log', 'couples'::resource_kind, 'Partners track small promises made and kept to rebuild reliability one step at a time.', 'Use it to help partners rebuild trust through small, visible follow-through.', array['Couples']::text[], 'One week, repeated', 'Both partners choose modest promises they can actually keep, such as texting when running late. The log records promise made, kept or missed and what happened. Missed promises are discussed without punishment. Go slowly and watch whether the partner who was hurt sets the pace; trust rebuilds on their timing, not the clock.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a small promise I will keep"}, {"id": "f1", "type": "textarea", "label": "Partner B: a small promise I will keep"}, {"id": "f2", "type": "textarea", "label": "What I did and whether I kept it"}, {"id": "f3", "type": "textarea", "label": "What my partner noticed"}, {"id": "f4", "type": "textarea", "label": "What was hard to follow through on"}, {"id": "f5", "type": "textarea", "label": "What we will promise for next week"}]'::jsonb, array['relationship issues', 'repair', 'couples']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('small-daily-rituals-partner-planner', 'Small Daily Rituals Partner Planner', 'couples'::resource_kind, 'A planner where partners choose small daily and weekly rituals for staying connected.', 'Use it to help partners pick small, regular moments that keep them close.', array['Couples']::text[], '30 minutes', 'Ask each partner about small moments they miss, such as a morning goodbye or a Friday walk, then pick a few both can keep. Small and repeated beats big and rare. Check next time which rituals stuck, and let go of ones that felt like chores rather than adding more.', '[{"id": "f0", "type": "textarea", "label": "Partner A: small moments I miss"}, {"id": "f1", "type": "textarea", "label": "Partner B: small moments I miss"}, {"id": "f2", "type": "textarea", "label": "Rituals we already have"}, {"id": "f3", "type": "textarea", "label": "A daily ritual we will try"}, {"id": "f4", "type": "textarea", "label": "A weekly ritual we will try"}, {"id": "f5", "type": "textarea", "label": "What will help us keep them going"}]'::jsonb, array['Gottman', 'connection', 'couples']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('feelings-weather-report-craft', 'Feelings Weather Report Craft', 'kids'::resource_kind, 'A child makes a paper weather report to show how they feel today with sun, cloud, rain or storm cards.', 'Use it to give a child a simple, playful way to share how they feel.', array['Children']::text[], '25 minutes', 'The child cuts or draws weather symbols and presents a pretend forecast about their day. Let them pick any symbol and any story; there are no wrong answers. The parent watches the report and asks one curious question, and can repeat it at breakfast or bedtime at home. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Today''s weather inside me"}, {"id": "f1", "type": "textarea", "label": "What made it that kind of weather"}, {"id": "f2", "type": "textarea", "label": "What the weather needs to change"}, {"id": "f3", "type": "textarea", "label": "A forecast for tomorrow"}, {"id": "f4", "type": "textarea", "label": "What my parent can do when it storms"}]'::jsonb, array['children', 'emotion identification', 'art']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-making-activity', 'Calm Down Jar Making Activity', 'kids'::resource_kind, 'A child fills a jar with glitter and water to watch swirls settle while practicing slow breathing.', 'Use it to give a child something to watch and hold while a big feeling settles.', array['Children']::text[], '30 minutes', 'Make the jar together and shake it while the child names a feeling. Watch the glitter settle for a few slow breaths. The parent joins in so the jar is something shared and not a consequence, and keeps it in a spot where the child can reach it. Seal the lid well and supervise younger children.', '[{"id": "f0", "type": "textarea", "label": "A feeling that shakes me up"}, {"id": "f1", "type": "textarea", "label": "What my body feels like when shaken"}, {"id": "f2", "type": "textarea", "label": "How I breathe while the glitter settles"}, {"id": "f3", "type": "textarea", "label": "What I notice when it is calm"}, {"id": "f4", "type": "textarea", "label": "Where my jar lives at home"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('superhero-strengths-cape-craft', 'Superhero Strengths Cape Craft', 'kids'::resource_kind, 'A child decorates a cape or cuff with their strengths and the powers they use to cope.', 'Use it to help a child name what they are good at and what helps them through hard things.', array['Children']::text[], '35 minutes', 'The child designs a hero and lists strengths and coping powers, such as asking for help or taking big breaths. Include effort and kindness along with talents. The parent adds powers they see in their child and ties the cape to a daily moment, such as wearing it before a hard task.', '[{"id": "f0", "type": "textarea", "label": "My hero name"}, {"id": "f1", "type": "textarea", "label": "My strengths and powers"}, {"id": "f2", "type": "textarea", "label": "The power I use when I feel scared"}, {"id": "f3", "type": "textarea", "label": "The power I use when I feel mad"}, {"id": "f4", "type": "textarea", "label": "A power my family sees in me"}]'::jsonb, array['children', 'strengths', 'art']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('worry-monster-feeding-box-play', 'Worry Monster Feeding Box Play', 'kids'::resource_kind, 'A child feeds written or drawn worries to a decorated box monster that keeps them for the parent to check.', 'Use it to give a child a safe, playful place to put worries outside their head.', array['Children']::text[], '30 minutes', 'Decorate a box together and cut a mouth. The child feeds it drawings or words about worries, and a parent opens it at a set time to talk through any the child wants to share. This gives worries a home without forcing a talk. Remind parents not to argue with the worry; listen and help find one next step.', '[{"id": "f0", "type": "textarea", "label": "What my worry monster looks like"}, {"id": "f1", "type": "textarea", "label": "A worry I will feed it today"}, {"id": "f2", "type": "textarea", "label": "How my body feels after I put it in"}, {"id": "f3", "type": "textarea", "label": "Who opens the box with me"}, {"id": "f4", "type": "textarea", "label": "When we will open the box"}]'::jsonb, array['children', 'worry', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('brave-body-breathing-buddy-game', 'Brave Body Breathing Buddy Game', 'kids'::resource_kind, 'A child lies down with a stuffed animal on their belly and watches it rise and fall during slow breathing play.', 'Use it to help a child feel their breath as a calming tool through play.', array['Children']::text[], '15 minutes', 'Lie the child down with a favorite stuffed animal on their belly and have them rock it gently with breath. Count in slow turns and make it silly to keep it fun. The parent does it too and offers it at bedtime or after a hard moment. Keep it short and stop if the child loses interest.', '[{"id": "f0", "type": "textarea", "label": "My buddy''s name"}, {"id": "f1", "type": "textarea", "label": "What it felt like to rock my buddy"}, {"id": "f2", "type": "textarea", "label": "When my breath felt slow"}, {"id": "f3", "type": "textarea", "label": "A time I could use this at home"}, {"id": "f4", "type": "textarea", "label": "What my parent and I will do together"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('feelings-charades-group-game', 'Feelings Charades Group Game', 'game'::resource_kind, 'Group members act out feelings without words while others guess, then talk about the clues.', 'Use it to help a group notice how feelings show up in faces, voices and bodies.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Prepare cards with feelings of varied intensity. Players take turns acting while others guess, then the actor says what the feeling is like for them. Debrief with questions about which feelings were hard to guess and what the body does. Set a rule that no one is pushed to act a feeling they would rather skip.', '[{"id": "f0", "type": "textarea", "label": "A feeling I found easy to act out"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to guess"}, {"id": "f2", "type": "textarea", "label": "What my body does with a strong feeling"}, {"id": "f3", "type": "textarea", "label": "A feeling I notice in others"}, {"id": "f4", "type": "textarea", "label": "What I learned from the debrief"}]'::jsonb, array['emotion identification', 'group', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('pick-a-skill-story-bingo', 'Pick-a-Skill Story Bingo', 'game'::resource_kind, 'Bingo cards filled with coping skills that players mark as they share when they used them.', 'Use it to help a group remember and trade coping skills they already have.', array['Groups', 'Teens']::text[], '40 minutes', 'Hand out cards with coping skills on each square. Players mark a square by telling a short story about using it. First to a line shares one skill someone else mentioned. Debrief on which skills were new, which surprised people and which they could try this week. Keep stories brief so everyone gets a turn.', '[{"id": "f0", "type": "textarea", "label": "A skill I have used"}, {"id": "f1", "type": "textarea", "label": "A skill I heard that I want to try"}, {"id": "f2", "type": "textarea", "label": "A skill I would add to the card"}, {"id": "f3", "type": "textarea", "label": "When I could use one this week"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how others cope"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('perspective-taking-story-dice', 'Perspective Taking Story Dice', 'game'::resource_kind, 'Players roll dice to build a short scenario and tell it from two different points of view.', 'Use it to help a group practice seeing a situation through another person''s eyes.', array['Groups', 'Teens']::text[], '35 minutes', 'Roll dice that pick a person, a place and a problem, and have two players tell the same event from each side. Rotate roles so everyone tries each view. Debrief by asking what changed when the story was told from the other side and when the group sees this in daily life. Keep scenarios fictional.', '[{"id": "f0", "type": "textarea", "label": "The story we rolled"}, {"id": "f1", "type": "textarea", "label": "What the first person felt and wanted"}, {"id": "f2", "type": "textarea", "label": "What the second person felt and wanted"}, {"id": "f3", "type": "textarea", "label": "What changed when I took the other view"}, {"id": "f4", "type": "textarea", "label": "Where I could use this in real life"}]'::jsonb, array['communication', 'group', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('gratitude-treasure-hunt-relay', 'Gratitude Treasure Hunt Relay', 'game'::resource_kind, 'Teams hunt around the room for items that prompt a gratitude share, passing a token along each round.', 'Use it to give a group a lively way to practice noticing what is good.', array['Groups', 'Children', 'Teens']::text[], '30 minutes', 'Hide or place objects around the room and send pairs to find them, then each finder shares something they are thankful for linked to the object. The token passes so everyone shares. Debrief on how noticing felt and which shares stuck with them. Keep the pace light and let people pass without comment.', '[{"id": "f0", "type": "textarea", "label": "Something I am grateful for today"}, {"id": "f1", "type": "textarea", "label": "Something small I almost missed"}, {"id": "f2", "type": "textarea", "label": "Something someone did for me"}, {"id": "f3", "type": "textarea", "label": "How it felt to share"}, {"id": "f4", "type": "textarea", "label": "How I could notice good things this week"}]'::jsonb, array['gratitude', 'group', 'play']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('calm-down-statues-freeze-game', 'Calm Down Statues Freeze Game', 'game'::resource_kind, 'A freeze-dance variation where players hold a calm pose and breathe whenever the music stops.', 'Use it to help children and groups practice stopping and settling the body.', array['Children', 'Groups']::text[], '20 minutes', 'Play music and have players move, then stop it so they freeze in a pose and take three slow breaths. Vary the rounds with slow motion or a feeling to move to. A parent or aide can join in. Debrief by asking what they noticed in their bodies when the music stopped and where else they could freeze and breathe.', '[{"id": "f0", "type": "textarea", "label": "What my body felt like when moving fast"}, {"id": "f1", "type": "textarea", "label": "What it felt like when I froze"}, {"id": "f2", "type": "textarea", "label": "How my breathing changed"}, {"id": "f3", "type": "textarea", "label": "A time I could freeze and breathe"}, {"id": "f4", "type": "textarea", "label": "Who I could play this with at home"}]'::jsonb, array['regulation', 'group', 'play', 'children']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('safe-place-inventory-page', 'Safe Place Inventory Page', 'worksheet'::resource_kind, 'A page where a client lists real places, objects and people that feel safe or steady right now.', 'Use it to help a client build a list of present-day anchors for steadiness.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep everything on the page in the present: where the client feels safest today, what they can see, hear or touch there, and who is nearby. Do not ask for details of past events. If the client drifts toward memories, gently return to the room and the five senses. The finished page is a reference for hard moments.', '[{"id": "f0", "type": "textarea", "label": "A place where I feel safest right now"}, {"id": "f1", "type": "textarea", "label": "What I can see there"}, {"id": "f2", "type": "textarea", "label": "What I can hear or touch there"}, {"id": "f3", "type": "textarea", "label": "A person or pet who helps me feel steady"}, {"id": "f4", "type": "textarea", "label": "An object I can keep close"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this page"}]'::jsonb, array['safety', 'grounding', 'PTSD and trauma']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('then-versus-now-orientation-cards', 'Then Versus Now Orientation Cards', 'cbt'::resource_kind, 'Cards that pair a reminder with a present-day fact check: date, place, what is around me.', 'Use it to help a client tell a reminder from present danger by checking the here and now.', array['Adults']::text[], '25 minutes', 'Have the client write a common reminder on one side and present-day facts on the other, such as today''s date and who is in the room. Do not review past events. The cards are a pacing tool and a way to orient. Practice using them in session first with a mild reminder, then agree on when the client might carry them.', '[{"id": "f0", "type": "textarea", "label": "A reminder that stirs things up"}, {"id": "f1", "type": "textarea", "label": "What my body tells me it means"}, {"id": "f2", "type": "textarea", "label": "Today''s date and where I am"}, {"id": "f3", "type": "textarea", "label": "What is actually around me right now"}, {"id": "f4", "type": "textarea", "label": "What is different now from then, in a sentence"}, {"id": "f5", "type": "textarea", "label": "What I can do next to steady myself"}]'::jsonb, array['core CBT', 'safety', 'grounding', 'PTSD and trauma']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('choosing-a-direction-after-hard-times-page', 'Choosing a Direction After Hard Times Page', 'act'::resource_kind, 'A page for naming values and one small step that moves a client toward what matters, at their own pace.', 'Use it to help a client reconnect with what matters while keeping the pace gentle.', array['Adults']::text[], '30 minutes', 'Keep this in the present and the future: what the client cares about, and one small step that fits their energy today. Do not ask for a story of what happened. If strong feelings arise, pause and use a grounding step before continuing. Let the client decide when to stop.', '[{"id": "f0", "type": "textarea", "label": "Something I care about"}, {"id": "f1", "type": "textarea", "label": "A part of my life I would like more of"}, {"id": "f2", "type": "textarea", "label": "One tiny step toward it"}, {"id": "f3", "type": "textarea", "label": "What might get in the way today"}, {"id": "f4", "type": "textarea", "label": "What helps me stay present while I try"}, {"id": "f5", "type": "textarea", "label": "Who could support me with this step"}]'::jsonb, array['core ACT', 'values', 'pacing', 'PTSD and trauma']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('wave-surfing-with-skills-card', 'Wave Surfing With Skills Card', 'dbt'::resource_kind, 'A pocket card that lists skills for getting through a rush of reminders: temperature, paced breathing, orienting.', 'Use it to give a client a short list of skills to use when reminders hit.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the card together from skills the client has already tried and liked. Include one temperature step, one breathing step and one orienting step. Practice each briefly in session while calm. If the client feels unsafe or thinks about harming themselves, they can call or text 988 at any time; make sure this is on the card.', '[{"id": "f0", "type": "textarea", "label": "A skill that cools my body down"}, {"id": "f1", "type": "textarea", "label": "A skill that slows my breathing"}, {"id": "f2", "type": "textarea", "label": "A way I can orient to the room"}, {"id": "f3", "type": "textarea", "label": "A person I can reach out to"}, {"id": "f4", "type": "textarea", "label": "The number to call or text if I feel unsafe: 988"}, {"id": "f5", "type": "textarea", "label": "Where I keep this card"}]'::jsonb, array['core DBT', 'distress tolerance', 'grounding', 'PTSD and trauma']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('five-senses-orientation-scavenger-game', 'Five Senses Orientation Scavenger Game', 'game'::resource_kind, 'A group game where players find items in the room for each sense and share one steadying thing they noticed.', 'Use it to give a group a playful way to practice orienting to the present.', array['Groups', 'Teens']::text[], '25 minutes', 'Call out a sense and give each player a minute to find something in the room that matches, then each shares one thing. Keep the room calm and the pace slow, and let players pass. No one is asked about the past. Debrief by asking what helped them feel more here and when they could use it outside the group.', '[{"id": "f0", "type": "textarea", "label": "Something I saw"}, {"id": "f1", "type": "textarea", "label": "Something I heard"}, {"id": "f2", "type": "textarea", "label": "Something I touched"}, {"id": "f3", "type": "textarea", "label": "Something that helped me feel more here"}, {"id": "f4", "type": "textarea", "label": "When I could try this outside the group"}]'::jsonb, array['grounding', 'group', 'play', 'PTSD and trauma']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('worry-versus-problem-sorting-sheet', 'Worry Versus Problem Sorting Sheet', 'worksheet'::resource_kind, 'A two-column page for separating worries that have a next step from worries that are open questions.', 'Use it to help a client sort what they can act on from what they cannot settle today.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list current worries and sort each into one column or the other. The solvable column gets one next step and a day; the open column gets a way of carrying uncertainty for now. Notice how many worries sit in the open column. Revisit the page next session and see which ones moved.', '[{"id": "f0", "type": "textarea", "label": "Worries on my mind"}, {"id": "f1", "type": "textarea", "label": "The ones I can do something about"}, {"id": "f2", "type": "textarea", "label": "One step I will take and when"}, {"id": "f3", "type": "textarea", "label": "The ones I cannot settle today"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself about those"}, {"id": "f5", "type": "textarea", "label": "How I feel after sorting"}]'::jsonb, array['worry', 'planning', 'anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('what-is-the-likelihood-and-what-could-i-handle-page', 'What Is the Likelihood and What Could I Handle Page', 'cbt'::resource_kind, 'A page that asks how likely a feared event is and, if it happened, what the client could do.', 'Use it to help a client weigh both the odds and their own coping.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask for the feared event, an honest rating of how likely it is, and then spend most of the time on what the client could do if it did happen. Many clients overestimate the odds and underestimate their coping. Do not argue the likelihood; let the questions do the work and note what the client says about their own resources.', '[{"id": "f0", "type": "textarea", "label": "The event I fear"}, {"id": "f1", "type": "textarea", "label": "How likely it feels from 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Evidence that it might happen"}, {"id": "f3", "type": "textarea", "label": "Evidence that it might not"}, {"id": "f4", "type": "textarea", "label": "If it did happen, what I could do"}, {"id": "f5", "type": "textarea", "label": "Who could help me"}, {"id": "f6", "type": "textarea", "label": "What I learned writing this"}]'::jsonb, array['core CBT', 'thinking traps', 'anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('anxiety-along-for-the-walk-practice', 'Anxiety Along for the Walk Practice', 'act'::resource_kind, 'A walking practice where a client carries anxiety as a companion and keeps moving toward something that matters.', 'Use it to help a client move with anxiety present instead of waiting for it to leave.', array['Adults']::text[], '25 minutes', 'Take a short walk in session or describe one. The client names the anxious thoughts and sensations as walking companions and notices their steps anyway. Ask what the client would do if anxiety came along. The aim is movement toward a valued place, not making the feeling go away.', '[{"id": "f0", "type": "textarea", "label": "Where I am walking toward and why it matters"}, {"id": "f1", "type": "textarea", "label": "What anxiety says on the way"}, {"id": "f2", "type": "textarea", "label": "What it feels like in my body"}, {"id": "f3", "type": "textarea", "label": "What I notice about my feet and surroundings"}, {"id": "f4", "type": "textarea", "label": "One step I will take with anxiety along"}]'::jsonb, array['core ACT', 'willingness', 'values', 'anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('check-the-facts-for-anxious-feelings-page', 'Check the Facts for Anxious Feelings Page', 'dbt'::resource_kind, 'A page that walks through the DBT steps for checking whether an emotion fits the facts.', 'Use it to help a client check whether the size of anxiety fits the situation.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through the steps: name the emotion, the event, the interpretation, the threat and the outcome. If the facts do not fit, the client practices acting opposite to the urge; if they do, they problem solve. Be careful to validate the feeling first, since checking facts can sound like disbelief if rushed.', '[{"id": "f0", "type": "textarea", "label": "The emotion I am feeling and how strong it is"}, {"id": "f1", "type": "textarea", "label": "What happened, only the facts"}, {"id": "f2", "type": "textarea", "label": "What I am telling myself about it"}, {"id": "f3", "type": "textarea", "label": "How likely the threat is"}, {"id": "f4", "type": "textarea", "label": "Does the strength of my feeling fit the facts"}, {"id": "f5", "type": "textarea", "label": "What I will do next"}]'::jsonb, array['core DBT', 'emotion regulation', 'anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('partner-plan-for-anxious-evenings-talk', 'Partner Plan for Anxious Evenings Talk', 'couples'::resource_kind, 'A guide for partners to agree on how they will respond when anxiety is high in the evening.', 'Use it to help a couple agree on supportive responses to anxiety without taking over.', array['Couples']::text[], '30 minutes', 'Each partner describes what helps and what does not. The anxious partner names what they want, such as company or space; the other says what they can offer. Watch for reassurance that keeps the cycle going and talk about gentler alternatives. Write a short plan both can keep and review it in a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps when my anxiety is high"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I find hard"}, {"id": "f4", "type": "textarea", "label": "Words we will use"}, {"id": "f5", "type": "textarea", "label": "A plan we will try this week"}]'::jsonb, array['support', 'couples', 'anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('small-pleasures-and-meaning-log', 'Small Pleasures and Meaning Log', 'worksheet'::resource_kind, 'A daily log for one pleasant moment and one meaningful moment, however small.', 'Use it to help a client notice small moments of enjoyment and meaning during low mood.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Ask the client to jot one moment of each kind per day, with a mood rating. On low days the entries may be tiny, and that counts. Review the log for links between activities and mood and let the client draw the conclusions. If thoughts of harm arise, complete a safety conversation in session and remind them that 988 can be called or texted.', '[{"id": "f0", "type": "textarea", "label": "One pleasant moment today"}, {"id": "f1", "type": "textarea", "label": "One meaningful moment today"}, {"id": "f2", "type": "textarea", "label": "My mood from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I was doing"}, {"id": "f4", "type": "textarea", "label": "Anything I want to do more of"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe I can call or text 988"}]'::jsonb, array['behavioral activation', 'self-monitoring', 'depression']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('all-or-nothing-day-rewrite-sheet', 'All or Nothing Day Rewrite Sheet', 'cbt'::resource_kind, 'A page for turning "the whole day was a failure" into a more precise account of what happened.', 'Use it to help a client replace sweeping day-level judgments with specifics.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to write the sweeping thought about a recent day, then list what actually happened in order, including small things that went fine. Look at the difference between the first sentence and the list. Keep it gentle; a client who feels flat may only manage a few lines, and that is enough to start.', '[{"id": "f0", "type": "textarea", "label": "The sweeping thought about my day"}, {"id": "f1", "type": "textarea", "label": "What actually happened, hour by hour"}, {"id": "f2", "type": "textarea", "label": "Things that went fine or okay"}, {"id": "f3", "type": "textarea", "label": "What I did even though it was hard"}, {"id": "f4", "type": "textarea", "label": "A more precise sentence about my day"}]'::jsonb, array['core CBT', 'thinking traps', 'depression']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('values-and-tiny-actions-ladder', 'Values and Tiny Actions Ladder', 'act'::resource_kind, 'A ladder that links a value to actions from tiny to larger so a client can match a step to their energy.', 'Use it to help a client pick a step that fits their energy while staying in line with a value.', array['Adults']::text[], '30 minutes', 'Pick one value and write actions from five seconds to an hour. On heavy days the client does the bottom rung, on better days they climb. The client chooses the rung; do not push. Ask what each action says about the value and what gets in the way, and revisit the ladder to add rungs as energy shifts.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "An action that takes under a minute"}, {"id": "f2", "type": "textarea", "label": "An action that takes ten minutes"}, {"id": "f3", "type": "textarea", "label": "An action that takes an hour"}, {"id": "f4", "type": "textarea", "label": "The rung I will do today"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself if I only do the bottom rung"}]'::jsonb, array['core ACT', 'values', 'committed action', 'depression']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-low-mood-withdrawal', 'Opposite Action for Low Mood Withdrawal', 'dbt'::resource_kind, 'A page for noticing the urge to withdraw and choosing a small opposite action that fits the facts.', 'Use it to help a client act opposite to withdrawal in small, doable steps.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the urge to withdraw and ask whether it fits the facts. If staying in does not serve the client''s goals, plan one small opposite action, such as texting one person. Validate how heavy it feels before suggesting action. Pick an action the client rates as doable and check on it next session.', '[{"id": "f0", "type": "textarea", "label": "The urge I am noticing"}, {"id": "f1", "type": "textarea", "label": "What my mood is telling me to do"}, {"id": "f2", "type": "textarea", "label": "Does the urge help me right now"}, {"id": "f3", "type": "textarea", "label": "A small opposite action I could take"}, {"id": "f4", "type": "textarea", "label": "When and how I will do it"}, {"id": "f5", "type": "textarea", "label": "How I will reward myself after"}]'::jsonb, array['core DBT', 'opposite action', 'depression']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('feelings-color-mountain-drawing', 'Feelings Color Mountain Drawing', 'kids'::resource_kind, 'A child colors a mountain with the colors of their moods and adds a small climber on the day they choose.', 'Use it to give a child a drawn way to show low or heavy feelings and what helps.', array['Children']::text[], '30 minutes', 'The child colors bands on a mountain to show moods and draws a small climber where they are today. Ask what would help the climber and let the parent add one idea. If a child talks about wanting to be dead or hurt, stay with them and follow safety and reporting steps; 988 can be called or texted by parents.', '[{"id": "f0", "type": "textarea", "label": "The colors of my mountain"}, {"id": "f1", "type": "textarea", "label": "Where my climber is today"}, {"id": "f2", "type": "textarea", "label": "What makes the climb heavier"}, {"id": "f3", "type": "textarea", "label": "What helps my climber"}, {"id": "f4", "type": "textarea", "label": "A grown-up who can walk with me"}]'::jsonb, array['children', 'art', 'depression']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('time-blindness-estimate-and-check-sheet', 'Time Blindness Estimate and Check Sheet', 'worksheet'::resource_kind, 'A page where a client guesses how long tasks take, times them and compares.', 'Use it to help a client build a more accurate sense of how long things take.', array['Adults', 'Teens']::text[], 'One week', 'Pick three everyday tasks and have the client guess the time, then time them. Many clients are surprised in both directions. The point is building a picture of reality they can plan around, not catching them out. Review which tasks were off and add buffers to the next week''s plan together.', '[{"id": "f0", "type": "textarea", "label": "Task and my guess"}, {"id": "f1", "type": "textarea", "label": "How long it really took"}, {"id": "f2", "type": "textarea", "label": "How far off I was"}, {"id": "f3", "type": "textarea", "label": "Tasks I tend to underestimate"}, {"id": "f4", "type": "textarea", "label": "The buffer I will add"}, {"id": "f5", "type": "textarea", "label": "What helped me notice the time"}]'::jsonb, array['planning', 'routines', 'ADHD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('starting-resistance-thought-check', 'Starting Resistance Thought Check', 'cbt'::resource_kind, 'A sheet for catching the thought that blocks starting a task and testing a smaller first move.', 'Use it to help a client shrink the first move on a task they keep putting off.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a task the client has been avoiding and the thought that shows up when they try to begin. Examine it kindly and then design a first move so small it is almost silly, such as opening the file. Review whether the first move got them going and what made it easier or harder.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The thought that shows up when I try to start"}, {"id": "f2", "type": "textarea", "label": "How it makes me feel"}, {"id": "f3", "type": "textarea", "label": "A tiny first move"}, {"id": "f4", "type": "textarea", "label": "When I will try it"}, {"id": "f5", "type": "textarea", "label": "What happened when I tried"}]'::jsonb, array['core CBT', 'planning', 'ADHD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('interest-and-importance-values-page', 'Interest and Importance Values Page', 'act'::resource_kind, 'A page that separates what feels interesting from what feels important and plans both.', 'Use it to help a client link tasks they find dull to values they care about.', array['Adults']::text[], '30 minutes', 'Have the client list tasks in two columns, interesting and important. For the important ones, ask what value each serves and write a sentence linking them. Dull tasks can matter without being exciting. Pair a dull task with something that makes it easier, and revisit the list in a week.', '[{"id": "f0", "type": "textarea", "label": "Tasks that feel interesting"}, {"id": "f1", "type": "textarea", "label": "Tasks that matter but feel dull"}, {"id": "f2", "type": "textarea", "label": "The value behind one dull task"}, {"id": "f3", "type": "textarea", "label": "A way to make it a little easier"}, {"id": "f4", "type": "textarea", "label": "When I will do it"}, {"id": "f5", "type": "textarea", "label": "How I will notice that I did it"}]'::jsonb, array['core ACT', 'values', 'ADHD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('mindful-focus-return-practice', 'Mindful Focus Return Practice', 'dbt'::resource_kind, 'A short practice for noticing when attention drifts and gently coming back, with a log.', 'Use it to help a client practice returning attention without scolding themselves.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one anchor such as breath or a sound for two minutes and count how many times attention drifts and returns. The count of returns is the practice. Many clients feel they failed when the mind wandered; reframe each return as a repetition. Build up the time gradually and try it on a task the client chooses.', '[{"id": "f0", "type": "textarea", "label": "The anchor I used"}, {"id": "f1", "type": "textarea", "label": "How many times my attention drifted"}, {"id": "f2", "type": "textarea", "label": "How I came back"}, {"id": "f3", "type": "textarea", "label": "What I said to myself"}, {"id": "f4", "type": "textarea", "label": "Where I could use this during the week"}]'::jsonb, array['core DBT', 'mindfulness', 'ADHD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('body-doubling-focus-sprint-game', 'Body Doubling Focus Sprint Game', 'game'::resource_kind, 'A group game where players work in short timed sprints alongside each other, then share what they finished.', 'Use it to give a group a lively way to try working alongside others.', array['Groups', 'Teens']::text[], '30 minutes', 'Set a visible timer for short sprints of five to ten minutes. Each player picks a small task, works silently next to others and shares what they got done. Celebrate any progress. Debrief by asking what helped them focus and whether a work buddy could help at home. Keep sprints short and the room quiet.', '[{"id": "f0", "type": "textarea", "label": "The task I picked for the sprint"}, {"id": "f1", "type": "textarea", "label": "What I finished"}, {"id": "f2", "type": "textarea", "label": "What helped me stay on it"}, {"id": "f3", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f4", "type": "textarea", "label": "Who could be my work buddy"}]'::jsonb, array['planning', 'group', 'play', 'ADHD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('substance-use-pattern-notes-page', 'Substance Use Pattern Notes Page', 'worksheet'::resource_kind, 'A page for noting when, where and with whom substance use or urges show up across a week.', 'Use it to help a client see the pattern around urges and substance use without judgment.', array['Adults']::text[], 'One week', 'Ask the client to jot urges and any substance use with the time, place, people and feeling around it. This is a record for the two of you to look at, not a test. Review it with curiosity: where are the clusters, and what small change in routine might matter. Praise honest recording, whatever the entries say.', '[{"id": "f0", "type": "textarea", "label": "When an urge or use happened"}, {"id": "f1", "type": "textarea", "label": "Where I was and who was around"}, {"id": "f2", "type": "textarea", "label": "What I felt just before"}, {"id": "f3", "type": "textarea", "label": "What I did and what happened next"}, {"id": "f4", "type": "textarea", "label": "What I wish I had done differently"}, {"id": "f5", "type": "textarea", "label": "One change to try this week"}]'::jsonb, array['substance use', 'urges', 'self-monitoring', 'addiction']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('urge-thought-and-permission-thought-sheet', 'Urge Thought and Permission Thought Sheet', 'cbt'::resource_kind, 'A sheet for catching permission thoughts, such as "just this once", and writing a reply.', 'Use it to help a client spot thoughts that give permission to use and answer them.', array['Adults']::text[], '30 minutes', 'Collect the thoughts that show up before substance use and look for the ones that give permission or minimize. For each, the client writes a reply in their own voice, drawing on goals they care about. Role-play replying aloud. Note any shame and name it as common; the sheet is a skill, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "A thought that gave me permission"}, {"id": "f1", "type": "textarea", "label": "What I was feeling then"}, {"id": "f2", "type": "textarea", "label": "What the thought leaves out"}, {"id": "f3", "type": "textarea", "label": "A reply in my own voice"}, {"id": "f4", "type": "textarea", "label": "What I care about that this affects"}, {"id": "f5", "type": "textarea", "label": "What I will do when it shows up again"}]'::jsonb, array['core CBT', 'urges', 'substance use', 'addiction']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('urge-surfing-and-values-practice', 'Urge Surfing and Values Practice', 'act'::resource_kind, 'A practice for noticing an urge rise, peak and fall while choosing a valued action.', 'Use it to help a client stay with an urge for a few minutes while acting on a value.', array['Adults']::text[], '25 minutes', 'Guide the client to notice where the urge sits in the body, how it shifts and what happens when they do not act on it for a few minutes. Link it to a value they want to act on. The aim is to ride out the urge, not to erase it. Debrief what the urge did over time and what the client did with the time.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body"}, {"id": "f1", "type": "textarea", "label": "How strong it was at the start from 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What it did over a few minutes"}, {"id": "f3", "type": "textarea", "label": "What I did instead"}, {"id": "f4", "type": "textarea", "label": "The value I acted on"}, {"id": "f5", "type": "textarea", "label": "What I learned about urges"}]'::jsonb, array['core ACT', 'urges', 'values', 'addiction']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-menu-for-urges', 'Distress Tolerance Menu for Urges', 'dbt'::resource_kind, 'A menu of short skills for riding out an urge, with a pick-two-before-acting rule.', 'Use it to give a client ready options for getting through the first minutes of an urge.', array['Adults']::text[], '25 minutes', 'Build the menu from skills the client has used: cold water, paced breathing, a walk, a call. The rule is to pick two before deciding what to do. Practice one in session. Treat any use as information to build on, not a failure; ask what would make the skills easier to reach when the urge is strong.', '[{"id": "f0", "type": "textarea", "label": "A skill that uses my body"}, {"id": "f1", "type": "textarea", "label": "A skill that uses my senses"}, {"id": "f2", "type": "textarea", "label": "A person I can call"}, {"id": "f3", "type": "textarea", "label": "A place I can go"}, {"id": "f4", "type": "textarea", "label": "The two I will pick first"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this menu"}]'::jsonb, array['core DBT', 'distress tolerance', 'urges', 'addiction']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('support-without-policing-talk-guide', 'Support Without Policing Talk Guide', 'couples'::resource_kind, 'A guide for partners to agree on how to support someone working on substance use without checking up.', 'Use it to help partners agree on support that respects trust and boundaries.', array['Couples']::text[], 'Full session', 'Each partner says what they need: the one working on substance use names helpful support, the other names their worries and limits. Agree on how and when to talk about hard days and what happens after a setback. Watch for monitoring that erodes trust, and keep the plan specific and short.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what support helps me"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like policing"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I worry about"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need for myself"}, {"id": "f4", "type": "textarea", "label": "What we agree to do after a hard day"}, {"id": "f5", "type": "textarea", "label": "When we will check in on this plan"}]'::jsonb, array['substance use', 'support', 'couples', 'addiction']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('what-anger-gives-and-costs-ledger', 'What Anger Gives and Costs Ledger', 'worksheet'::resource_kind, 'A two-sided ledger for what anger has given a client and what it has cost them.', 'Use it to help a client see both what anger does for them and what it costs.', array['Adults', 'Teens']::text[], '30 minutes', 'Let the client list what anger gives them, such as respect or energy, as well as the costs. Do not argue the benefits away. The ledger usually shows the same goals could be reached in other ways. Ask what the client wants anger to do for them and plan one alternative route.', '[{"id": "f0", "type": "textarea", "label": "What my anger gives me"}, {"id": "f1", "type": "textarea", "label": "What my anger costs me"}, {"id": "f2", "type": "textarea", "label": "What I really want in those moments"}, {"id": "f3", "type": "textarea", "label": "Another way to get that"}, {"id": "f4", "type": "textarea", "label": "Who else is affected"}, {"id": "f5", "type": "textarea", "label": "One thing I will try"}]'::jsonb, array['triggers', 'self-monitoring', 'anger management']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('should-statements-flexibility-sheet', 'Should Statements Flexibility Sheet', 'cbt'::resource_kind, 'A sheet for turning rigid "should" statements into preferences and exploring the flexibility.', 'Use it to help a client loosen rigid rules that fuel anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Gather the "should" statements behind recent anger and rewrite each as "I would prefer" or "it would be better if." Ask how each version feels in the body. Rules matter to the client and it is not about dropping them; it is about holding them with room to move. Review one real example together.', '[{"id": "f0", "type": "textarea", "label": "A \"should\" that drives my anger"}, {"id": "f1", "type": "textarea", "label": "Who I am saying it about"}, {"id": "f2", "type": "textarea", "label": "A rewrite beginning \"I would prefer\""}, {"id": "f3", "type": "textarea", "label": "How my body feels with each version"}, {"id": "f4", "type": "textarea", "label": "What I can do when the rule is broken"}]'::jsonb, array['core CBT', 'automatic thoughts', 'anger management']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('anger-and-what-i-stand-for-page', 'Anger and What I Stand For Page', 'act'::resource_kind, 'A page that connects the care underneath anger with a values-based action.', 'Use it to help a client find what they care about under anger and act on it.', array['Adults']::text[], '30 minutes', 'Ask what the client cares about in the situations that spark anger, such as fairness or respect. Then ask what an action in line with that care would look like, other than the angry response. Keep it about choice, not suppressing anger. Rehearse the new action aloud.', '[{"id": "f0", "type": "textarea", "label": "A situation where I got angry"}, {"id": "f1", "type": "textarea", "label": "What I care about in it"}, {"id": "f2", "type": "textarea", "label": "What my angry reaction did"}, {"id": "f3", "type": "textarea", "label": "An action that fits what I care about"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself to stay with it"}]'::jsonb, array['core ACT', 'values', 'anger management']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('pause-and-wise-mind-stop-skill-card', 'Pause and Wise Mind Stop Skill Card', 'dbt'::resource_kind, 'A card that lists the STOP skill steps with space to add personal cues.', 'Use it to give a client a short pause routine before reacting in anger.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach the four steps: stop, take a step back, observe, proceed mindfully. Have the client add personal cues, such as unclenching hands. Rehearse it in a mild role-play. Review next session when they used it and what they did after the pause.', '[{"id": "f0", "type": "textarea", "label": "The first sign that anger is rising for me"}, {"id": "f1", "type": "textarea", "label": "My version of stop"}, {"id": "f2", "type": "textarea", "label": "What I observe in my body"}, {"id": "f3", "type": "textarea", "label": "What I observe about the situation"}, {"id": "f4", "type": "textarea", "label": "What I will do next"}, {"id": "f5", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['core DBT', 'regulation', 'anger management']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-drawing-and-tools', 'Anger Thermometer Drawing and Tools', 'kids'::resource_kind, 'A child colors a thermometer from calm to boiling and adds a tool for each level.', 'Use it to help a child notice anger levels and pick a tool for each one.', array['Children']::text[], '30 minutes', 'The child colors a thermometer and draws what they look like at each level, then picks a tool for each, such as stomping in place or asking for space. Parent practices the tools with them and notices early signs. Keep tools about the body and calm, never about hurting. If a child discloses harm at home, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What I look like when I am calm"}, {"id": "f1", "type": "textarea", "label": "What I look like when I start to heat up"}, {"id": "f2", "type": "textarea", "label": "What I look like when I boil over"}, {"id": "f3", "type": "textarea", "label": "A tool for each level"}, {"id": "f4", "type": "textarea", "label": "What my parent will do to help"}]'::jsonb, array['children', 'regulation', 'art', 'anger management']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('reassurance-seeking-tally-page', 'Reassurance Seeking Tally Page', 'worksheet'::resource_kind, 'A page for counting when a client asks for reassurance and what happens to the doubt afterward.', 'Use it to help a client notice how often they seek reassurance and its short-term effect.', array['Adults', 'Teens']::text[], 'One week', 'Have the client tally each time they ask someone or look something up to feel sure, and rate the doubt before and after. Many see relief fade quickly. Do this with curiosity and without shame. The pattern gives you a starting point for a gradual plan the client sets the pace on.', '[{"id": "f0", "type": "textarea", "label": "What I wanted to be sure about"}, {"id": "f1", "type": "textarea", "label": "Who or what I asked"}, {"id": "f2", "type": "textarea", "label": "Doubt before from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Doubt after from 0 to 10"}, {"id": "f4", "type": "textarea", "label": "How long the relief lasted"}, {"id": "f5", "type": "textarea", "label": "What I noticed over the week"}]'::jsonb, array['uncertainty', 'self-monitoring', 'OCD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('thought-is-not-action-check-sheet', 'Thought Is Not Action Check Sheet', 'cbt'::resource_kind, 'A sheet that separates having a thought from meaning it or acting on it.', 'Use it to help a client examine the idea that a thought carries special meaning.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick an intrusive thought the client finds upsetting and look at what they believe having it says about them. Ask where that rule comes from and whether they apply it to other people. Do not offer reassurance that the thought will not happen; focus on how the mind produces thoughts, and practice carrying one.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought that bothers me"}, {"id": "f1", "type": "textarea", "label": "What I believe having it means"}, {"id": "f2", "type": "textarea", "label": "Where that rule comes from"}, {"id": "f3", "type": "textarea", "label": "Does it apply to everyone"}, {"id": "f4", "type": "textarea", "label": "What I value that this thought clashes with"}, {"id": "f5", "type": "textarea", "label": "How I can carry the thought today"}]'::jsonb, array['core CBT', 'thinking traps', 'OCD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('doubt-and-direction-choice-point', 'Doubt and Direction Choice Point', 'act'::resource_kind, 'A choice point page that maps a doubting moment, the urge to check, and a values-based move.', 'Use it to help a client choose between a checking move and a values move.', array['Adults']::text[], '30 minutes', 'Map the moment: the doubt, the feelings, the urge to check or fix, and the two moves available. Ask where each move leads in the long run. The client picks what to try next time and what support helps. Keep it kind; the urge is strong and choosing a different move is hard.', '[{"id": "f0", "type": "textarea", "label": "The doubt that shows up"}, {"id": "f1", "type": "textarea", "label": "The feelings that come with it"}, {"id": "f2", "type": "textarea", "label": "The move that gives short relief"}, {"id": "f3", "type": "textarea", "label": "A move toward what I value"}, {"id": "f4", "type": "textarea", "label": "Where each move leads over time"}, {"id": "f5", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['core ACT', 'values', 'OCD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('wise-mind-check-before-rituals-card', 'Wise Mind Check Before Rituals Card', 'dbt'::resource_kind, 'A card with a short pause and three questions to ask before giving in to a ritual.', 'Use it to help a client add a pause and a choice before a ritual.', array['Adults', 'Teens']::text[], '20 minutes', 'Build a pause of a few breaths and three questions: what am I feeling, what does my wise mind say, what is one thing I could do instead. Rehearse it in session with a mild example. Delay is a first step toward reducing a ritual, so set the pause at a length the client can keep.', '[{"id": "f0", "type": "textarea", "label": "What I am feeling right now"}, {"id": "f1", "type": "textarea", "label": "What my wise mind says"}, {"id": "f2", "type": "textarea", "label": "What I could do instead of the ritual"}, {"id": "f3", "type": "textarea", "label": "How long I will wait first"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself while I wait"}]'::jsonb, array['core DBT', 'regulation', 'OCD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('worry-brain-bluff-card-game', 'Worry Brain Bluff Card Game', 'game'::resource_kind, 'A group card game where players bluff about what the doubt voice says and then answer it with a plan.', 'Use it to give a group a light way to talk back to doubt and practice sitting with it.', array['Groups', 'Teens']::text[], '30 minutes', 'Players draw cards with doubting thoughts, read them in a silly doubting voice and the group suggests a reply that does not give reassurance, such as "maybe, maybe not." Debrief how it felt to hear the doubt out loud and what helped. Keep it playful and let anyone skip a card.', '[{"id": "f0", "type": "textarea", "label": "A doubt that sounded familiar"}, {"id": "f1", "type": "textarea", "label": "A reply I liked"}, {"id": "f2", "type": "textarea", "label": "What it felt like to hear it aloud"}, {"id": "f3", "type": "textarea", "label": "What I will try when it comes up"}, {"id": "f4", "type": "textarea", "label": "What I learned from the group"}]'::jsonb, array['uncertainty', 'group', 'play', 'OCD']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('panic-wave-timeline-page', 'Panic Wave Timeline Page', 'worksheet'::resource_kind, 'A page for mapping the rise, peak and fall of a panic wave from start to finish.', 'Use it to help a client see that panic rises and falls over minutes.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to chart a recent wave: first sensations, the peak and how it eased. Look at the shape of the curve and how long it lasted. Many clients are surprised how short the peak is. Use the timeline to prepare a plan for riding the next wave.', '[{"id": "f0", "type": "textarea", "label": "What I felt first"}, {"id": "f1", "type": "textarea", "label": "What I thought was happening"}, {"id": "f2", "type": "textarea", "label": "The peak, and how long it lasted"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "How it eased"}, {"id": "f5", "type": "textarea", "label": "What I would like to try next time"}]'::jsonb, array['self-monitoring', 'anxiety', 'panic attacks']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('catastrophic-misreading-of-sensations-sheet', 'Catastrophic Misreading of Sensations Sheet', 'cbt'::resource_kind, 'A sheet that pairs a body sensation with the scary reading and a more balanced one.', 'Use it to help a client test the scary meaning they give to body sensations.', array['Adults']::text[], '25 minutes', 'List sensations such as a racing heart and the meaning the client gives them. Together write a more balanced reading, such as "my body is alarmed and will settle." Then plan a small experiment, such as a brisk walk, to see what happens. Check medical concerns with the client''s physician.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice"}, {"id": "f1", "type": "textarea", "label": "What I fear it means"}, {"id": "f2", "type": "textarea", "label": "Evidence for and against that"}, {"id": "f3", "type": "textarea", "label": "A more balanced reading"}, {"id": "f4", "type": "textarea", "label": "An experiment I could try"}, {"id": "f5", "type": "textarea", "label": "What I found out"}]'::jsonb, array['core CBT', 'thinking traps', 'panic attacks']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('making-room-for-a-racing-heart-practice', 'Making Room for a Racing Heart Practice', 'act'::resource_kind, 'A practice for letting the sensations of panic be present while choosing an action that matters.', 'Use it to help a client make room for body sensations and keep moving toward a value.', array['Adults']::text[], '25 minutes', 'Have the client notice sensations without fighting them, describing size, shape and place, and then choose an action that matters. The practice is about willingness, not calming. Start with a mild sensation. Ask what the client has been avoiding because of panic and what they would do if it came along.', '[{"id": "f0", "type": "textarea", "label": "The sensations I notice"}, {"id": "f1", "type": "textarea", "label": "How I describe them without judgment"}, {"id": "f2", "type": "textarea", "label": "What I usually do to fight them"}, {"id": "f3", "type": "textarea", "label": "What I would do if they could come along"}, {"id": "f4", "type": "textarea", "label": "A step toward what matters"}]'::jsonb, array['core ACT', 'willingness', 'panic attacks']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('cold-water-and-paced-breathing-panic-card', 'Cold Water and Paced Breathing Panic Card', 'dbt'::resource_kind, 'A card with a short sequence for a wave of panic: cool the face, slow the out-breath, orient.', 'Use it to give a client a short body-based sequence to try during panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice the sequence in session so it is familiar: cool water or a cold pack on the face, long out-breaths, then naming things in the room. Offer it as one way to help the body settle. Clients with heart or breathing conditions should check with their physician before using cold on the face.', '[{"id": "f0", "type": "textarea", "label": "Cold step I can use"}, {"id": "f1", "type": "textarea", "label": "Breathing step I will use"}, {"id": "f2", "type": "textarea", "label": "Orienting step I will use"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I practiced"}]'::jsonb, array['core DBT', 'distress tolerance', 'panic attacks']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('panic-moment-teamwork-script', 'Panic Moment Teamwork Script', 'couples'::resource_kind, 'A script for partners to follow when one has a wave of panic, with words to say and things to leave unsaid.', 'Use it to help a couple agree on calm, steady support during panic.', array['Couples']::text[], '30 minutes', 'The partner who has panic says what helps, such as a steady voice, and what does not, such as being told to calm down. The other partner practices the words. Rehearse once in session. Review after a real moment and adjust the script without blame.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me in the moment"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: words I will say"}, {"id": "f3", "type": "textarea", "label": "Partner B: things I will not say"}, {"id": "f4", "type": "textarea", "label": "After the wave passes, what we do"}, {"id": "f5", "type": "textarea", "label": "When we will review the script"}]'::jsonb, array['support', 'couples', 'panic attacks']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('special-time-planning-sheet', 'Special Time Planning Sheet', 'worksheet'::resource_kind, 'A page for planning short one-on-one child-led time each day.', 'Use it to help a parent plan regular child-led time that strengthens connection.', array['Adults']::text[], '25 minutes', 'Help the parent choose a short daily window, even ten minutes, where the child leads and the parent follows without correcting or teaching. Practice describing what the child is doing. Expect slips such as giving directions and keep the plan modest. Review how it went and what the child enjoyed.', '[{"id": "f0", "type": "textarea", "label": "When special time can happen each day"}, {"id": "f1", "type": "textarea", "label": "What my child likes to play"}, {"id": "f2", "type": "textarea", "label": "How I will follow their lead"}, {"id": "f3", "type": "textarea", "label": "What I will avoid doing during it"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['connection', 'parenting']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('parent-trigger-thought-log', 'Parent Trigger Thought Log', 'cbt'::resource_kind, 'A log for catching thoughts that rise when a child misbehaves and what they lead the parent to do.', 'Use it to help a parent notice the thoughts that drive reactions to a child''s behavior.', array['Adults']::text[], '25 minutes', 'Pick a recent moment of conflict and trace the thought, the feeling and the action. Common thoughts include "they are doing this on purpose." Write a more balanced thought and plan a calmer first response. Be warm; many parents carry guilt, and the aim is a small shift in how they respond.', '[{"id": "f0", "type": "textarea", "label": "What my child did"}, {"id": "f1", "type": "textarea", "label": "The thought that went through my mind"}, {"id": "f2", "type": "textarea", "label": "How I felt"}, {"id": "f3", "type": "textarea", "label": "What I did next"}, {"id": "f4", "type": "textarea", "label": "A more balanced thought"}, {"id": "f5", "type": "textarea", "label": "What I would like to do next time"}]'::jsonb, array['core CBT', 'automatic thoughts', 'parenting']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('parenting-values-and-daily-moments-page', 'Parenting Values and Daily Moments Page', 'act'::resource_kind, 'A page that links a parent''s values to small everyday moments with their child.', 'Use it to help a parent act on what matters to them in ordinary moments.', array['Adults']::text[], '30 minutes', 'Ask what kind of parent the client wants to be and what their child would say they stood for. Then pick small daily moments, such as dinner, where they can live it. Stay compassionate about moments that fall short. Plan one moment to try and check back next session.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be"}, {"id": "f1", "type": "textarea", "label": "A moment this week that fit it"}, {"id": "f2", "type": "textarea", "label": "A moment that did not and what got in the way"}, {"id": "f3", "type": "textarea", "label": "A daily moment I can use"}, {"id": "f4", "type": "textarea", "label": "What I will do next time"}]'::jsonb, array['core ACT', 'values', 'parenting']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('validate-then-limit-practice-page', 'Validate Then Limit Practice Page', 'dbt'::resource_kind, 'A page for pairing a validating sentence with a clear limit when a child is upset.', 'Use it to help a parent acknowledge a child''s feeling and still hold a limit.', array['Adults']::text[], '30 minutes', 'Write pairs: first the feeling, then the limit, such as "You are upset the screen is off, and it stays off." Rehearse aloud in session and take turns playing the child. Many parents find it easier than expected. Note when validation sounds like giving in and adjust the wording.', '[{"id": "f0", "type": "textarea", "label": "A recent limit I set"}, {"id": "f1", "type": "textarea", "label": "What my child felt"}, {"id": "f2", "type": "textarea", "label": "A sentence that validates the feeling"}, {"id": "f3", "type": "textarea", "label": "A sentence that holds the limit"}, {"id": "f4", "type": "textarea", "label": "The two together"}, {"id": "f5", "type": "textarea", "label": "How I will practice this week"}]'::jsonb, array['core DBT', 'validation', 'parenting']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('family-rules-and-rewards-poster-craft', 'Family Rules and Rewards Poster Craft', 'kids'::resource_kind, 'A family designs a poster of a few clear rules and the kind ways they will notice effort.', 'Use it to help a family agree on a few simple rules and positive notice of effort.', array['Children', 'Adults']::text[], 'Full session', 'The child and parent decorate a poster with three or four rules written positively and ways to notice when they happen. Let the child help choose. The parent commits to noticing effort before mistakes. Hang it where all can see and review it together weekly.', '[{"id": "f0", "type": "textarea", "label": "Rules we will follow"}, {"id": "f1", "type": "textarea", "label": "Ways we notice when someone follows them"}, {"id": "f2", "type": "textarea", "label": "What the child will draw on the poster"}, {"id": "f3", "type": "textarea", "label": "What the parent will do when a rule is hard"}, {"id": "f4", "type": "textarea", "label": "When we will look at it together"}]'::jsonb, array['children', 'family', 'parenting']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('good-enough-day-planner-for-new-parents', 'Good-Enough Day Planner for New Parents', 'worksheet'::resource_kind, 'A planner for choosing the few things that make a day good enough during the early months.', 'Use it to help a new parent set a gentle, realistic bar for each day.', array['Adults']::text[], '25 minutes', 'Ask what a good-enough day looks like with a baby or pregnancy, and pick two or three anchors such as eating, sleep when possible and one outing. Normalize leaving things undone. If the parent mentions thoughts of harming themselves or the baby, discuss it in session at once; 988 can be called or texted.', '[{"id": "f0", "type": "textarea", "label": "What a good-enough day looks like for me"}, {"id": "f1", "type": "textarea", "label": "Two or three anchors I will keep"}, {"id": "f2", "type": "textarea", "label": "Things I will let go of for now"}, {"id": "f3", "type": "textarea", "label": "Help I can ask for"}, {"id": "f4", "type": "textarea", "label": "A small thing I will do for myself"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['support', 'planning', 'self-compassion', 'perinatal and postpartum']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('mom-guilt-and-dad-guilt-thought-sheet', 'Mom Guilt and Dad Guilt Thought Sheet', 'cbt'::resource_kind, 'A sheet for examining "I should be doing more" thoughts that show up with a new baby.', 'Use it to help a parent weigh guilt thoughts against what they are really doing.', array['Adults']::text[], '25 minutes', 'Collect the guilt thoughts and ask what standard each one assumes and where it came from. Compare it with what the parent would say to a friend. Write a kinder, more accurate version. Social media and relatives are often hidden sources; ask about them without judgment.', '[{"id": "f0", "type": "textarea", "label": "A guilt thought I have"}, {"id": "f1", "type": "textarea", "label": "The standard behind it"}, {"id": "f2", "type": "textarea", "label": "Where I learned that standard"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f4", "type": "textarea", "label": "A kinder, more accurate thought"}]'::jsonb, array['core CBT', 'self-criticism', 'perinatal and postpartum']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('values-through-sleepless-weeks-practice', 'Values Through Sleepless Weeks Practice', 'act'::resource_kind, 'A practice for acting on a value in tiny ways while tired and stretched.', 'Use it to help a parent live a value in small actions when energy is low.', array['Adults']::text[], '25 minutes', 'Choose one value, such as warmth, and brainstorm very small ways to live it in a day with a baby. Allow that a tired person may only manage a smile or a quiet minute. Ask what tiredness tells them and make room for it. Revisit after a week.', '[{"id": "f0", "type": "textarea", "label": "A value I care about as a parent"}, {"id": "f1", "type": "textarea", "label": "Tiny ways to live it in a day"}, {"id": "f2", "type": "textarea", "label": "What tiredness tells me"}, {"id": "f3", "type": "textarea", "label": "What I will do despite that"}, {"id": "f4", "type": "textarea", "label": "A moment this week I will notice"}]'::jsonb, array['core ACT', 'values', 'perinatal and postpartum']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('self-soothing-with-the-five-senses-baby-time-kit', 'Self-Soothing With the Five Senses Baby Time Kit', 'dbt'::resource_kind, 'A kit of quick self-soothing ideas for each sense that fit while holding or feeding a baby.', 'Use it to help a parent calm themselves in short moments during baby care.', array['Adults']::text[], '20 minutes', 'Go through the five senses and pick ideas that work with a baby in arms, such as warm tea, a favorite song or a soft blanket. Keep each idea under two minutes. Clients often forget their own needs; invite them to try one a day and share what helped next time.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that soothes me"}, {"id": "f1", "type": "textarea", "label": "Something I can hear"}, {"id": "f2", "type": "textarea", "label": "Something I can smell"}, {"id": "f3", "type": "textarea", "label": "Something I can taste"}, {"id": "f4", "type": "textarea", "label": "Something I can touch"}, {"id": "f5", "type": "textarea", "label": "The one I will try tomorrow"}]'::jsonb, array['core DBT', 'self-soothing', 'perinatal and postpartum']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('sleep-and-support-split-planner-for-partners', 'Sleep and Support Split Planner for Partners', 'couples'::resource_kind, 'A planner for partners to divide night care, rest and help in a way both can live with.', 'Use it to help partners share night care, rest and support fairly.', array['Couples']::text[], '30 minutes', 'Ask each partner about their sleep, needs and limits, and map nights so each gets protected rest. Include time for the recovering parent when relevant. Revisit as the baby changes and keep room for tired tempers; plan a short check-in each week about what is working.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my needs for rest and help"}, {"id": "f1", "type": "textarea", "label": "Partner B: my needs for rest and help"}, {"id": "f2", "type": "textarea", "label": "How we will split nights"}, {"id": "f3", "type": "textarea", "label": "Time each of us gets for ourselves"}, {"id": "f4", "type": "textarea", "label": "What we will do when we are both worn out"}, {"id": "f5", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['relationship issues', 'perinatal and postpartum']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('strengths-evidence-folder-page', 'Strengths Evidence Folder Page', 'worksheet'::resource_kind, 'A page for collecting evidence of strengths from real moments, messages and actions.', 'Use it to help a client gather concrete proof of their strengths.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list moments from recent months when they showed a strength and who noticed. Concrete moments matter more than adjectives. Clients may brush off compliments; ask them to record them anyway. Add an entry each week and read the folder together from time to time.', '[{"id": "f0", "type": "textarea", "label": "A moment I showed a strength"}, {"id": "f1", "type": "textarea", "label": "What the strength was"}, {"id": "f2", "type": "textarea", "label": "Who noticed or what they said"}, {"id": "f3", "type": "textarea", "label": "A compliment I tend to brush off"}, {"id": "f4", "type": "textarea", "label": "What I want to add this week"}]'::jsonb, array['strengths', 'self-monitoring', 'self-esteem']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('inner-critic-courtroom-worksheet', 'Inner Critic Courtroom Worksheet', 'cbt'::resource_kind, 'A page that puts the inner critic on trial: charges, evidence, defense and verdict.', 'Use it to help a client examine the inner critic''s claims like evidence in a trial.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client name the critic''s charge, then list evidence for and against it, call a defense witness who knows them well and write a verdict in balanced words. Keep it a little playful. Note any evidence the client excludes without noticing.', '[{"id": "f0", "type": "textarea", "label": "The charge my inner critic makes"}, {"id": "f1", "type": "textarea", "label": "Evidence for the charge"}, {"id": "f2", "type": "textarea", "label": "Evidence against it"}, {"id": "f3", "type": "textarea", "label": "What a kind witness would say"}, {"id": "f4", "type": "textarea", "label": "My verdict in balanced words"}]'::jsonb, array['core CBT', 'self-criticism', 'self-esteem']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('worth-without-conditions-reflection', 'Worth Without Conditions Reflection', 'act'::resource_kind, 'A reflection that explores the difference between worth that depends on performance and worth that does not.', 'Use it to help a client notice conditions they attach to their own worth.', array['Adults']::text[], '30 minutes', 'Ask what the client has to achieve to feel okay about themselves and where that rule came from. Explore what it would be like to act on values without waiting for the rule to be met. Hold the discussion lightly; let the client reach their own words about worth.', '[{"id": "f0", "type": "textarea", "label": "What I think I must achieve to feel okay"}, {"id": "f1", "type": "textarea", "label": "Where that rule came from"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "A time I acted on a value without it"}, {"id": "f4", "type": "textarea", "label": "What I want to try instead"}]'::jsonb, array['core ACT', 'self-compassion', 'self-esteem']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('build-positive-experiences-calendar', 'Build Positive Experiences Calendar', 'dbt'::resource_kind, 'A calendar for planning small positive experiences to build good feelings and self-respect.', 'Use it to help a client schedule small things that build positive feelings.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a few short, short-term positives the client can do soon and one long-term goal to work on. Place them on a calendar with times. Notice pleasant moments when they happen. Ask what gets in the way and adjust, because plans that are too big often collapse.', '[{"id": "f0", "type": "textarea", "label": "A short-term positive I can do soon"}, {"id": "f1", "type": "textarea", "label": "When I will do it"}, {"id": "f2", "type": "textarea", "label": "One long-term goal"}, {"id": "f3", "type": "textarea", "label": "A small step toward it this week"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I did it"}]'::jsonb, array['core DBT', 'emotion regulation', 'self-esteem']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('strengths-spotlight-card-game', 'Strengths Spotlight Card Game', 'game'::resource_kind, 'A group game where players draw strength cards and share a time they used it.', 'Use it to give a group a safe way to name and own strengths.', array['Groups', 'Teens']::text[], '30 minutes', 'Deal strength cards and have players tell a short story about using one, then the group names another strength they heard. Keep comments specific and kind. Debrief how it felt to hear strengths named and where the group might notice them outside. Players may pass.', '[{"id": "f0", "type": "textarea", "label": "A strength card I drew"}, {"id": "f1", "type": "textarea", "label": "A time I used it"}, {"id": "f2", "type": "textarea", "label": "A strength others named in me"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear it"}, {"id": "f4", "type": "textarea", "label": "Where I will notice it this week"}]'::jsonb, array['strengths', 'group', 'play', 'self-esteem']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('safety-behaviors-spotting-sheet', 'Safety Behaviors Spotting Sheet', 'worksheet'::resource_kind, 'A sheet that lists things a client does to feel safer in social settings and what they cost.', 'Use it to help a client notice habits that protect them but keep them stuck.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect behaviors like rehearsing sentences, avoiding eye contact or staying near the door. Ask what each is meant to prevent and what it costs in connection. Pick one to drop for a small test in a low-stakes setting and review next session.', '[{"id": "f0", "type": "textarea", "label": "A social situation I find hard"}, {"id": "f1", "type": "textarea", "label": "What I do to feel safer"}, {"id": "f2", "type": "textarea", "label": "What I am afraid would happen without it"}, {"id": "f3", "type": "textarea", "label": "What it costs me"}, {"id": "f4", "type": "textarea", "label": "One I could drop in a small test"}]'::jsonb, array['avoidance', 'social anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('post-event-replay-rewrite', 'Post-Event Replay Rewrite', 'cbt'::resource_kind, 'A sheet for reviewing a social event after it happened, separating what occurred from the harsh replay.', 'Use it to help a client check the harsh replay against what really happened.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to describe what happened and what their mind replayed. Compare facts with interpretations and count the positive or neutral moments. Many clients cannot recall them without prompts. Write a short, fair summary the client can read before the next event.', '[{"id": "f0", "type": "textarea", "label": "What happened, just the facts"}, {"id": "f1", "type": "textarea", "label": "What my mind keeps replaying"}, {"id": "f2", "type": "textarea", "label": "What went fine or neutral"}, {"id": "f3", "type": "textarea", "label": "What others did that I forgot"}, {"id": "f4", "type": "textarea", "label": "A fair summary of the event"}]'::jsonb, array['core CBT', 'thinking traps', 'social anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('showing-up-anyway-values-page', 'Showing Up Anyway Values Page', 'act'::resource_kind, 'A page about showing up to social moments with anxiety along because connection matters.', 'Use it to help a client link social steps to what they value.', array['Adults']::text[], '30 minutes', 'Ask what connection the client misses and which value it serves, such as friendship. Pick one low-stakes step and name the anxious thoughts that may come along. The goal is the step, not feeling calm. Plan when, where and who, and debrief what happened.', '[{"id": "f0", "type": "textarea", "label": "A connection I miss"}, {"id": "f1", "type": "textarea", "label": "The value behind it"}, {"id": "f2", "type": "textarea", "label": "A small social step"}, {"id": "f3", "type": "textarea", "label": "Thoughts that may come along"}, {"id": "f4", "type": "textarea", "label": "What I will do when they show up"}]'::jsonb, array['core ACT', 'values', 'social anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-starter-script-page', 'Interpersonal Effectiveness Starter Script Page', 'dbt'::resource_kind, 'A page for drafting short conversation starters and follow-ups using DBT skills.', 'Use it to help a client prepare a few simple lines for starting and ending talks.', array['Adults', 'Teens']::text[], '30 minutes', 'Draft two openers, two follow-up questions and one way to leave gracefully. Practice them aloud with you playing the other person. Use GIVE skills to keep it warm. Clients often over-prepare; aim for lines that sound like them and a plan to use one this week.', '[{"id": "f0", "type": "textarea", "label": "An opener in my voice"}, {"id": "f1", "type": "textarea", "label": "A follow-up question"}, {"id": "f2", "type": "textarea", "label": "A way to show interest"}, {"id": "f3", "type": "textarea", "label": "A way to end the chat kindly"}, {"id": "f4", "type": "textarea", "label": "When I will try one"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'social anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('courage-chart-for-social-steps', 'Courage Chart for Social Steps', 'kids'::resource_kind, 'A child and parent build a chart of small social steps and add stickers or drawings as each is tried.', 'Use it to help a child take small, playful social steps with a parent cheering them on.', array['Children']::text[], '30 minutes', 'The child and parent draw a path of steps, from waving to a neighbor to asking someone to play, and pick the first. Parent cheers effort, not outcome, and does not push. Reward trying, whatever happens. Review the chart weekly and add steps the child chooses.', '[{"id": "f0", "type": "textarea", "label": "The first step on my path"}, {"id": "f1", "type": "textarea", "label": "The step I want to reach"}, {"id": "f2", "type": "textarea", "label": "How my body feels when I try"}, {"id": "f3", "type": "textarea", "label": "Who cheers for me"}, {"id": "f4", "type": "textarea", "label": "What I will draw when I try a step"}]'::jsonb, array['children', 'exposure', 'social anxiety']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('continuing-bonds-ideas-page', 'Continuing Bonds Ideas Page', 'worksheet'::resource_kind, 'A page for ways a client can stay connected to someone who died while living on.', 'Use it to help a client find ways to keep a bond with someone they lost.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask what the client wants to keep of the person, such as a recipe, a song or a saying, and what they might do with it. Grief has no schedule; accept sadness as part of the work. Choose one small act for the coming week and revisit it next time.', '[{"id": "f0", "type": "textarea", "label": "Something I want to keep of them"}, {"id": "f1", "type": "textarea", "label": "A way I could honor it"}, {"id": "f2", "type": "textarea", "label": "A ritual I would like"}, {"id": "f3", "type": "textarea", "label": "Who I could share this with"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week"}]'::jsonb, array['support', 'connection', 'grief and loss']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('unfinished-business-letter-page', 'Unfinished Business Letter Page', 'cbt'::resource_kind, 'A page for writing a letter to the person who died to say what was left unsaid, kept in the client''s hands.', 'Use it to help a client say what was left unsaid, at their pace and in their own words.', array['Adults']::text[], '30 minutes', 'The client may write what they wish they had said, and does not have to share it. You can offer to listen to any part they choose. Check how they feel after writing and give time to settle. For complicated relationships, go slowly and let the client set the pace.', '[{"id": "f0", "type": "textarea", "label": "What I wish I had said"}, {"id": "f1", "type": "textarea", "label": "What I want them to know"}, {"id": "f2", "type": "textarea", "label": "What I am still carrying"}, {"id": "f3", "type": "textarea", "label": "What I would like to let go of"}, {"id": "f4", "type": "textarea", "label": "How I feel after writing"}]'::jsonb, array['core CBT', 'grief and loss']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('making-room-for-sorrow-and-love-practice', 'Making Room for Sorrow and Love Practice', 'act'::resource_kind, 'A practice that holds sorrow as a sign of love and chooses a small valued action.', 'Use it to help a client make room for grief while still acting on what matters.', array['Adults']::text[], '25 minutes', 'Invite the client to notice where sorrow sits in the body and what it says about what they loved. Link it to a small action in honor of that love. Avoid steering the client away from pain; let the practice hold both. Check how the client feels at the end.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "Where I feel sorrow in my body"}, {"id": "f2", "type": "textarea", "label": "What the sorrow says about love"}, {"id": "f3", "type": "textarea", "label": "A small action in honor of them"}, {"id": "f4", "type": "textarea", "label": "What I need to take care of myself"}]'::jsonb, array['core ACT', 'values', 'grief and loss']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('riding-the-grief-wave-with-skills-card', 'Riding the Grief Wave With Skills Card', 'dbt'::resource_kind, 'A card with skills to use when waves of grief arrive: self-soothe, ride, reach out.', 'Use it to give a client skills for waves of grief.', array['Adults']::text[], '20 minutes', 'Make a card with a self-soothing step, a way to ride the wave without fighting it and a person to reach out to. Practice one in session. Waves can arrive without warning, so make the card portable. If a client mentions thoughts of ending their life, talk it through in session; 988 can be called or texted.', '[{"id": "f0", "type": "textarea", "label": "A self-soothing step"}, {"id": "f1", "type": "textarea", "label": "A way to ride the wave"}, {"id": "f2", "type": "textarea", "label": "A person I can reach out to"}, {"id": "f3", "type": "textarea", "label": "What I tell myself during a wave"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['core DBT', 'self-soothing', 'grief and loss']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('memory-box-decorating-craft', 'Memory Box Decorating Craft', 'kids'::resource_kind, 'A child decorates a box and fills it with drawings and small objects that remind them of someone they lost.', 'Use it to give a child a drawn and built way to remember someone.', array['Children']::text[], '35 minutes', 'The child decorates a box and fills it with items and drawings. The parent shares a memory and listens to the child''s. Let the child lead and stop when they want. Children grieve in bursts and play in between, which is normal. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Who this box is for"}, {"id": "f1", "type": "textarea", "label": "Something I remember"}, {"id": "f2", "type": "textarea", "label": "Something I put in the box"}, {"id": "f3", "type": "textarea", "label": "How I feel when I look at it"}, {"id": "f4", "type": "textarea", "label": "Who I can show it to"}]'::jsonb, array['children', 'art', 'grief and loss']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('relationship-patterns-reflection-page', 'Relationship Patterns Reflection Page', 'worksheet'::resource_kind, 'A page for noticing repeated patterns across relationships and what the client brings to them.', 'Use it to help a client notice patterns across their relationships.', array['Adults']::text[], '30 minutes', 'Ask the client to describe two or three relationships and look for common threads in how they start, how conflict goes and how they end. Hold it lightly; patterns are not blame. Ask which pattern they would like to change first and what small step would test it.', '[{"id": "f0", "type": "textarea", "label": "A relationship that mattered"}, {"id": "f1", "type": "textarea", "label": "How it started and how conflict went"}, {"id": "f2", "type": "textarea", "label": "A thread that repeats"}, {"id": "f3", "type": "textarea", "label": "What I bring to it"}, {"id": "f4", "type": "textarea", "label": "A pattern I want to change"}, {"id": "f5", "type": "textarea", "label": "A small step this week"}]'::jsonb, array['communication', 'self-monitoring', 'relationship issues']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('assumptions-about-their-motives-check', 'Assumptions About Their Motives Check', 'cbt'::resource_kind, 'A sheet for checking assumptions about why someone acted and testing alternatives.', 'Use it to help a client check assumptions about other people''s intentions.', array['Adults']::text[], '25 minutes', 'Pick a recent moment the client read as a slight, then list other possible reasons. Ask how they could find out and what they would do with the answer. Most clients end up planning a conversation. Rehearse the opening sentence in session.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant"}, {"id": "f2", "type": "textarea", "label": "Other possible reasons"}, {"id": "f3", "type": "textarea", "label": "How I could find out"}, {"id": "f4", "type": "textarea", "label": "What I will say or do"}]'::jsonb, array['core CBT', 'thinking traps', 'relationship issues']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('relationship-values-and-actions-page', 'Relationship Values and Actions Page', 'act'::resource_kind, 'A page linking what a client values in relationships to specific actions this week.', 'Use it to help a client act on relationship values through small steps.', array['Adults']::text[], '30 minutes', 'Ask what kind of friend, partner or family member the client wants to be and note moments they acted that way. Then plan two actions for the week. Notice where old habits pull them away and ask what they will do. Keep goals within the client''s control.', '[{"id": "f0", "type": "textarea", "label": "The kind of person I want to be in my relationships"}, {"id": "f1", "type": "textarea", "label": "A recent moment I lived it"}, {"id": "f2", "type": "textarea", "label": "An action for this week"}, {"id": "f3", "type": "textarea", "label": "What old habit may show up"}, {"id": "f4", "type": "textarea", "label": "What I will do then"}]'::jsonb, array['core ACT', 'values', 'relationship issues']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('give-and-fast-combined-conversation-card', 'GIVE and FAST Combined Conversation Card', 'dbt'::resource_kind, 'A card that combines GIVE and FAST skills for a conversation where the relationship and self-respect both matter.', 'Use it to help a client prepare for a hard conversation with a person they want to keep.', array['Adults', 'Teens']::text[], '30 minutes', 'Prepare one real conversation and write a line for each skill. Rehearse it twice, once smoothly and once with pushback. Ask which part feels hardest, and rehearse that part again. Debrief after the real conversation to see what to adjust.', '[{"id": "f0", "type": "textarea", "label": "The conversation I need to have"}, {"id": "f1", "type": "textarea", "label": "A gentle line for them"}, {"id": "f2", "type": "textarea", "label": "A fair line for me"}, {"id": "f3", "type": "textarea", "label": "An honest line"}, {"id": "f4", "type": "textarea", "label": "What I will do if they push back"}, {"id": "f5", "type": "textarea", "label": "How I will care for myself after"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'relationship issues']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('repair-attempt-phrases-list', 'Repair Attempt Phrases List', 'couples'::resource_kind, 'Partners build a short list of phrases that help them repair during a disagreement.', 'Use it to help partners agree on repair phrases that actually work for them.', array['Couples']::text[], '25 minutes', 'Each partner writes phrases that would help them de-escalate, such as "can we take a break" or "I am sorry for my tone." Share the lists and choose five that both will accept. Practice using one in a mild disagreement in session. Agree how to receive a repair without saying "too late."', '[{"id": "f0", "type": "textarea", "label": "Partner A: phrases that help me soften"}, {"id": "f1", "type": "textarea", "label": "Partner B: phrases that help me soften"}, {"id": "f2", "type": "textarea", "label": "Five we both accept"}, {"id": "f3", "type": "textarea", "label": "How we will receive a repair attempt"}, {"id": "f4", "type": "textarea", "label": "When we will practice"}]'::jsonb, array['Gottman', 'repair', 'relationship issues']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('trusted-adults-and-support-contacts-page', 'Trusted Adults and Support Contacts Page', 'worksheet'::resource_kind, 'A page for listing safe people, what each can help with and how to reach them.', 'Use it to help a client map people who can support them and how to contact them.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep the page in the present: who feels safe, what each person can help with and how to reach them. Do not ask for details of what happened. Include a professional line and 988 by call or text. If a minor discloses abuse, follow your reporting duties and explain them in plain words.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe to me"}, {"id": "f1", "type": "textarea", "label": "What each person can help with"}, {"id": "f2", "type": "textarea", "label": "How I can reach them"}, {"id": "f3", "type": "textarea", "label": "A professional or helpline I can contact"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}, {"id": "f5", "type": "textarea", "label": "Who I will tell about this page"}]'::jsonb, array['safety', 'support', 'sexual abuse']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('self-blame-fact-check-without-details', 'Self-Blame Fact Check Without Details', 'cbt'::resource_kind, 'A sheet for examining self-blame thoughts using present-day facts about responsibility, without retelling events.', 'Use it to help a client look at self-blame thoughts without writing about what happened.', array['Adults']::text[], '25 minutes', 'Work only with the thought itself, such as "it was my fault," and ask what the client would say to a friend who held it. Do not ask for a description of events and do not assign this as homework. Pace it and stop to ground if distress rises. Responsibility lies with the person who harmed.', '[{"id": "f0", "type": "textarea", "label": "The thought I notice"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it from 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who thought this"}, {"id": "f3", "type": "textarea", "label": "What I notice in my body"}, {"id": "f4", "type": "textarea", "label": "A steadier thought for today"}, {"id": "f5", "type": "textarea", "label": "What helps me ground now"}]'::jsonb, array['core CBT', 'pacing', 'self-criticism', 'sexual abuse']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('choosing-safety-and-connection-values-page', 'Choosing Safety and Connection Values Page', 'act'::resource_kind, 'A page that links safety, connection and care to small choices a client can make today.', 'Use it to help a client choose small steps toward safety and connection at their own pace.', array['Adults']::text[], '30 minutes', 'Ask what safety and connection mean to the client now and one small step that fits. Keep the focus on the present and the client''s choice. They set the pace and can say no to any part. Check in on how they are feeling and ground before closing.', '[{"id": "f0", "type": "textarea", "label": "What safety means to me today"}, {"id": "f1", "type": "textarea", "label": "A person or place that feels connected"}, {"id": "f2", "type": "textarea", "label": "One small choice I can make today"}, {"id": "f3", "type": "textarea", "label": "What makes it hard"}, {"id": "f4", "type": "textarea", "label": "What helps me feel steady"}]'::jsonb, array['core ACT', 'values', 'grounding', 'sexual abuse']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('boundaries-and-saying-no-practice-cards', 'Boundaries and Saying No Practice Cards', 'dbt'::resource_kind, 'Cards for practicing short sentences that set a boundary, with a plan for support afterward.', 'Use it to help a client rehearse boundaries in small, safe steps.', array['Adults', 'Teens']::text[], '30 minutes', 'Practice low-stakes boundary lines first and let the client choose the wording. Use DEAR MAN where it fits. Include a plan for support afterward. Never require the client to practice with someone who is unsafe; rehearse with you or a safe person only.', '[{"id": "f0", "type": "textarea", "label": "A small boundary I can set"}, {"id": "f1", "type": "textarea", "label": "The words I will use"}, {"id": "f2", "type": "textarea", "label": "Who I will practice with"}, {"id": "f3", "type": "textarea", "label": "What I will do if I feel uneasy"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to afterward"}]'::jsonb, array['core DBT', 'boundaries', 'interpersonal effectiveness', 'sexual abuse']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('my-body-safety-circles-drawing', 'My Body Safety Circles Drawing', 'kids'::resource_kind, 'A child draws circles of people by how close they may be and learns the body safety rules.', 'Use it to help a child learn body safety rules and who to tell, using drawing.', array['Children']::text[], '30 minutes', 'The child draws circles from closest to farthest and places people in them, then practices the rules: my body is mine, I can say no and I can tell a trusted adult. Remind parents the child is not to blame. Reporting duties apply if a child discloses anything; follow your agency''s steps and tell the child and parent what will happen next.', '[{"id": "f0", "type": "textarea", "label": "People in my closest circle"}, {"id": "f1", "type": "textarea", "label": "People I know but am less close to"}, {"id": "f2", "type": "textarea", "label": "Strangers"}, {"id": "f3", "type": "textarea", "label": "The grown-ups I can tell"}, {"id": "f4", "type": "textarea", "label": "What I can say if I feel uncomfortable"}]'::jsonb, array['children', 'safety', 'art', 'sexual abuse']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-builder-by-feeling', 'Coping Toolbox Builder by Feeling', 'worksheet'::resource_kind, 'A page that sorts coping skills into boxes for different feelings and situations.', 'Use it to help a client build a toolbox with the right tools for each feeling.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask which feelings come up most and what the client does now, then fill in a few tools for each one. Note which tools are only available at home. Have them try one tool from each box before the next session and bring back what worked.', '[{"id": "f0", "type": "textarea", "label": "A feeling that comes up a lot"}, {"id": "f1", "type": "textarea", "label": "Tools I already use for it"}, {"id": "f2", "type": "textarea", "label": "A new tool to try"}, {"id": "f3", "type": "textarea", "label": "A tool I can use anywhere"}, {"id": "f4", "type": "textarea", "label": "What I noticed after trying it"}]'::jsonb, array['skills', 'planning', 'coping skills']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('believable-coping-statement-cards', 'Believable Coping Statement Cards', 'cbt'::resource_kind, 'Index cards with realistic coping statements for hard moments, written in the client''s own voice.', 'Use it to help a client write coping thoughts that sound believable to them.', array['Adults', 'Teens']::text[], '25 minutes', 'Collect coping statements the client believes at least a little, not slogans. Test each by saying it aloud and rating how believable it feels. Adjust the wording until it rings true. Keep the cards where they will be used, such as a phone note.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I face"}, {"id": "f1", "type": "textarea", "label": "What I tell myself now"}, {"id": "f2", "type": "textarea", "label": "A coping thought I could believe"}, {"id": "f3", "type": "textarea", "label": "How believable it is from 0 to 100"}, {"id": "f4", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['core CBT', 'skills', 'coping skills']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('workable-or-not-coping-review', 'Workable or Not Coping Review', 'act'::resource_kind, 'A review of current coping strategies and whether each one works in the short and long run.', 'Use it to help a client check whether their habits move them toward what matters.', array['Adults']::text[], '30 minutes', 'List the client''s go-to strategies and ask for each: does it help in the moment, and where does it lead over months. No strategy is bad in itself; it is a question of fit. Pick one to keep, one to adjust and one to add.', '[{"id": "f0", "type": "textarea", "label": "A coping habit I use a lot"}, {"id": "f1", "type": "textarea", "label": "What it does for me right now"}, {"id": "f2", "type": "textarea", "label": "Where it leads over time"}, {"id": "f3", "type": "textarea", "label": "Does it move me toward what matters"}, {"id": "f4", "type": "textarea", "label": "One I will keep, adjust or add"}]'::jsonb, array['core ACT', 'workability', 'coping skills']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('accumulate-positives-daily-menu', 'Accumulate Positives Daily Menu', 'dbt'::resource_kind, 'A menu of everyday positives for building resilience before hard moments hit.', 'Use it to help a client build daily positives to buffer stress.', array['Adults', 'Teens']::text[], '25 minutes', 'Build a menu of small, regular positives such as a walk, a call or music. The client picks one each day and logs it. Distinguish coping in the moment from building a buffer in advance. Review next session which items fit easily into the week.', '[{"id": "f0", "type": "textarea", "label": "Small positives I enjoy"}, {"id": "f1", "type": "textarea", "label": "Ones I can do in ten minutes"}, {"id": "f2", "type": "textarea", "label": "One I will do each day"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my mood"}]'::jsonb, array['core DBT', 'emotion regulation', 'coping skills']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('act-out-a-skill-team-relay', 'Act-Out-a-Skill Team Relay', 'game'::resource_kind, 'A relay game where teams act out coping skills for others to guess, then name when they would use them.', 'Use it to give a group a fun way to review and remember coping skills.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Prepare cards with coping skills and have teams act them out. After each guess, the actor names a moment they could use it. Keep it light and let anyone pass. Debrief which skills were new and which they want to try this week.', '[{"id": "f0", "type": "textarea", "label": "A skill I recognized"}, {"id": "f1", "type": "textarea", "label": "A skill I want to try"}, {"id": "f2", "type": "textarea", "label": "A moment I could use it"}, {"id": "f3", "type": "textarea", "label": "What I learned from the others"}, {"id": "f4", "type": "textarea", "label": "My pick for this week"}]'::jsonb, array['group', 'play', 'coping skills']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('avoidance-map-for-feared-situations', 'Avoidance Map for Feared Situations', 'worksheet'::resource_kind, 'A map of places and activities a client avoids and what that avoidance costs.', 'Use it to help a client see how avoiding a fear shapes daily life.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list what they avoid or arrange around, including small workarounds. Rate how much each limits them. This is a starting point for a ladder, not a push to face things. Choose one item that matters most to the client.', '[{"id": "f0", "type": "textarea", "label": "Things I avoid because of this fear"}, {"id": "f1", "type": "textarea", "label": "Workarounds I use"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "What I would do if I were not afraid"}, {"id": "f4", "type": "textarea", "label": "The item that matters most"}]'::jsonb, array['avoidance', 'exposure', 'phobias']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('fear-feared-outcome-and-coping-page', 'Fear Feared Outcome and Coping Page', 'cbt'::resource_kind, 'A page that pairs the feared outcome with the client''s plan for coping if it happened.', 'Use it to help a client think through what they fear and how they could cope.', array['Adults']::text[], '30 minutes', 'Name the feared outcome clearly, rate how likely it feels and then spend time on how the client would cope. Plan a small exposure step to check the prediction. Keep steps within the client''s agreement; they choose the pace and can pause.', '[{"id": "f0", "type": "textarea", "label": "What I fear will happen"}, {"id": "f1", "type": "textarea", "label": "How likely it feels from 0 to 100"}, {"id": "f2", "type": "textarea", "label": "How I would cope if it did"}, {"id": "f3", "type": "textarea", "label": "A small step to test it"}, {"id": "f4", "type": "textarea", "label": "What I found out"}]'::jsonb, array['core CBT', 'exposure', 'phobias']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('fear-and-direction-willingness-page', 'Fear and Direction Willingness Page', 'act'::resource_kind, 'A page for choosing a valued activity that sits near a fear and making room for the fear on the way.', 'Use it to help a client choose willingness for the sake of something they care about.', array['Adults']::text[], '30 minutes', 'Ask what the fear keeps the client from, and why it matters. Pick a step and rate willingness. Name the thoughts and sensations that come along. Offer the step as a choice, not a test, and plan how to acknowledge the fear without arguing with it.', '[{"id": "f0", "type": "textarea", "label": "What matters to me that the fear blocks"}, {"id": "f1", "type": "textarea", "label": "A step toward it"}, {"id": "f2", "type": "textarea", "label": "My willingness from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What the fear says"}, {"id": "f4", "type": "textarea", "label": "What I will do with it on board"}]'::jsonb, array['core ACT', 'willingness', 'values', 'phobias']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('opposite-action-approach-steps-card', 'Opposite Action Approach Steps Card', 'dbt'::resource_kind, 'A card with small approach steps that act opposite to the urge to avoid when avoiding does not fit the facts.', 'Use it to help a client approach a feared thing in small steps.', array['Adults', 'Teens']::text[], '25 minutes', 'Check the facts together and, if the fear does not fit the danger, plan a step opposite to avoidance. Use body posture and a confident voice as part of acting opposite. Rehearse in imagination first. Review how it went and adjust the step size.', '[{"id": "f0", "type": "textarea", "label": "The fear and the urge to avoid"}, {"id": "f1", "type": "textarea", "label": "Does the fear fit the facts"}, {"id": "f2", "type": "textarea", "label": "A small approach step"}, {"id": "f3", "type": "textarea", "label": "Body posture I will use"}, {"id": "f4", "type": "textarea", "label": "How I will reward myself"}]'::jsonb, array['core DBT', 'opposite action', 'phobias']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('brave-explorer-passport-craft', 'Brave Explorer Passport Craft', 'kids'::resource_kind, 'A child makes a passport and collects stamps for each small step toward a feared thing, with a parent as guide.', 'Use it to give a child a playful record of small, brave steps.', array['Children']::text[], '30 minutes', 'The child decorates a passport and draws small steps from far away to near. Each try earns a stamp, whatever the result. The parent models calm and does not push or trick the child. Go at the child''s pace and review weekly.', '[{"id": "f0", "type": "textarea", "label": "The thing I want to get closer to"}, {"id": "f1", "type": "textarea", "label": "My first small step"}, {"id": "f2", "type": "textarea", "label": "How I feel in my body"}, {"id": "f3", "type": "textarea", "label": "What my parent will do"}, {"id": "f4", "type": "textarea", "label": "What my stamp will look like"}]'::jsonb, array['children', 'exposure', 'play', 'phobias']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('what-my-body-lets-me-do-page', 'What My Body Lets Me Do Page', 'worksheet'::resource_kind, 'A page that lists activities and moments a client''s body makes possible.', 'Use it to help a client notice what their body does for them rather than how it looks.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list everyday things their body makes possible, such as hugging someone or walking to a favorite place. Do not discuss appearance, size or shape. Notice any resistance and keep the page about function and experience. Add to it each week.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do"}, {"id": "f1", "type": "textarea", "label": "A moment this week I was glad of my body"}, {"id": "f2", "type": "textarea", "label": "A person I can hug, walk or dance with"}, {"id": "f3", "type": "textarea", "label": "What I appreciate on a hard day"}, {"id": "f4", "type": "textarea", "label": "One more I will add this week"}]'::jsonb, array['self-compassion', 'strengths', 'body image']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('mirror-and-media-thought-check-sheet', 'Mirror and Media Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for noticing thoughts that rise from social media or the mirror and testing them.', 'Use it to help a client examine thoughts triggered by media or mirrors.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client sees and thinks when scrolling or passing a mirror and how it shifts their mood. Look at which accounts leave them feeling worse and which help. Test small changes, such as muting accounts. Keep the focus on thoughts and feelings, never on measuring or comparing the body.', '[{"id": "f0", "type": "textarea", "label": "Where I notice these thoughts"}, {"id": "f1", "type": "textarea", "label": "What I tell myself"}, {"id": "f2", "type": "textarea", "label": "How it changes my mood"}, {"id": "f3", "type": "textarea", "label": "A kinder, fairer thought"}, {"id": "f4", "type": "textarea", "label": "A small change I can try with my media"}]'::jsonb, array['core CBT', 'self-talk', 'body image']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('living-fully-beyond-appearance-practice', 'Living Fully Beyond Appearance Practice', 'act'::resource_kind, 'A practice for choosing actions that fit values even when appearance thoughts show up.', 'Use it to help a client act on values while appearance thoughts are present.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask what the client has skipped because of appearance thoughts and what they would do if the thoughts could come along. Choose one activity and plan it. Practice noticing the thoughts as thoughts. Revisit how it went and what mattered most.', '[{"id": "f0", "type": "textarea", "label": "Something I have skipped because of these thoughts"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "The thoughts that show up"}, {"id": "f3", "type": "textarea", "label": "What I will do with them along"}, {"id": "f4", "type": "textarea", "label": "When I will do it"}]'::jsonb, array['core ACT', 'defusion', 'body image']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('self-validation-and-opposite-action-for-hiding', 'Self-Validation and Opposite Action for Hiding', 'dbt'::resource_kind, 'A page that validates the urge to hide and plans an opposite action that fits the facts.', 'Use it to help a client respond kindly to urges to hide and take a small step out.', array['Adults', 'Teens']::text[], '25 minutes', 'Validate the feeling first and then check whether hiding serves the client''s goals. Plan one small opposite action, such as going to an event for twenty minutes. Include a kind sentence to say to oneself. Review how it went and adjust the step.', '[{"id": "f0", "type": "textarea", "label": "The urge to hide and when it shows up"}, {"id": "f1", "type": "textarea", "label": "A validating sentence to myself"}, {"id": "f2", "type": "textarea", "label": "Does hiding help my goals"}, {"id": "f3", "type": "textarea", "label": "A small opposite action"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself afterward"}]'::jsonb, array['core DBT', 'opposite action', 'body image']::text[], '2026-10-13T15:00:00+00:00'::timestamptz),
  ('compliments-beyond-looks-group-game', 'Compliments Beyond Looks Group Game', 'game'::resource_kind, 'A group game where players give and receive compliments about character, effort and actions.', 'Use it to give a group practice noticing and naming what is good beyond appearance.', array['Groups', 'Teens']::text[], '30 minutes', 'Deal prompt cards such as "someone who is a good listener" and have players offer a compliment on character or action only, never looks. Debrief how it felt to receive them and how to keep noticing outside the group. Players may pass at any time.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "A compliment I received"}, {"id": "f2", "type": "textarea", "label": "What it felt like to receive it"}, {"id": "f3", "type": "textarea", "label": "A quality I like in myself"}, {"id": "f4", "type": "textarea", "label": "How I will notice it this week"}]'::jsonb, array['strengths', 'group', 'play', 'body image']::text[], '2026-10-13T15:00:00+00:00'::timestamptz)
